INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K4K2Z3MFADWNXQA39GAEK', 'penang-walking-notes', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-07T08:28:15.000Z', '2026-10-20T04:18:58.974Z', '2024-10-07T08:28:15.000Z', NULL, NULL, 3, '01M5BRH9YSTP80B1WV6Y2Y0K0M', NULL, 'zh-TW', '01M59K4K2Z3MFADWNXQA39GAEK', '馬來筆記 Part.1 行路不難(上)', '{"id":"01M59KM20VSZQJFYPKEXSZVN2D","provider":"local","filename":"IMG_20240830_085054-scaled.jpg","mimeType":"image/jpeg","width":2560,"height":1920,"blurhash":"L$G9UKofkYo#pfWYWsbIRka}adax","dominantColor":"rgb(121,128,146)","alt":"馬來筆記 Part.1 行路不難(上)","meta":{"storageKey":"01M59KM1H3XRT3PS4T1VTYESCD.jpg","caption":null,"blurhash":"L$G9UKofkYo#pfWYWsbIRka}adax","dominantColor":"rgb(121,128,146)"}}', '[{"_type":"block","_key":"key-2-ziawy","style":"normal","children":[{"_type":"span","_key":"key-1-e260w","text":"前陣子去了大馬一趟，離開檳城時，當地朋友拜託我回台後把旅途體驗分享出來，讓更多台灣人去大馬旅遊。人越老越怕欠人情，這趟受馬來西亞熟識或不認識的人太多幫助，既然答應了，那就盡全力做到心安理得吧！全系列很長，預計接近十篇。"}]},{"_type":"image","_key":"key-3-l257f","asset":{"_type":"reference","_ref":"01M59MGY6MNHTGFXVRCWHZ3YQP","url":"/_emdash/api/media/file/01M59MGY6MNHTGFXVRCWHZ3YQP.jpg"},"alt":""},{"_type":"block","_key":"key-5-0h1gq","style":"normal","children":[{"_type":"span","_key":"key-4-aaeg1","text":"個人討厭走觀光客行程，也不想用旅遊部落客老套的時序類寫法，加上本身有史地、文化研究、飲食消費…的相關背景，所以打算用幾篇不同面向的主題、隨筆的方式來分享這趟大馬旅行。"}]},{"_type":"block","_key":"key-12-lqslj","style":"normal","children":[{"_type":"span","_key":"key-6-pzchg","text":"\n"},{"_type":"span","_key":"key-7-dffh4","text":"先讓大家對馬來西亞有個較具體的比例認知。\n\n","marks":["strong"]},{"_type":"span","_key":"key-8-1namf","text":"馬來西亞本島南北長度大約是台灣兩倍，寬度則差不多，同樣西側的開發程度遠高於東部，東部較多人煙稀少的自然景觀與海景景點，國土中央一樣是山脈，東西之間有經過山區的橫貫公路，跟台灣一樣，都是風景漂亮但又較危險的山路，而馬來西亞還有一大塊國土位於砂勞越，感覺又更原始了。\n\n"},{"_type":"span","_key":"key-9-buydy","text":"以此估算城市之間的距離，例如這趟我是由北部的檳城入境，中部的吉隆坡離開，兩者的距離就大約是台北到高雄，開車 5-6 小時，國內線飛機 1 小時內，同理，中部的吉隆坡到南部的新山、柔佛等地，也差不多是北高的距離，如果你跟我一樣，有要在大馬跨城市移動，這個估算法能比較快掌握距離感，所以位於檳城與吉隆坡之間的怡保、太平，就是台北到台中彰化的距離，開車 2-3 小時，掌握距離也就比較好選擇最適合的交通方式：飛機、輕航機、機車、火車、巴士、自駕、包車、計程車、坐船…等。\n\n"},{"_type":"span","_key":"key-10-22seb","text":"原先想要自駕，還好沒有，馬來西亞是右駕，我非常不習慣右駕，之前有次去日本租車，差點瘋掉，一路自我懷疑駕照是雞腿換來的，又驚又怕反而失去駕駛的樂趣，另外檳城的市中心路很窄，單向道很多，可能得非常熟悉路況的人較適合。當然，如果你很習慣右駕，又或是去東馬這類公共運輸較不便的點，可嘗試自駕，下次我打算租重機😌\n\n"},{"_type":"span","_key":"key-11-kol6s","text":"這趟我多數是徒步搭配 Grab 計程車，幾段跨城市移動是用火車（發生好多誇張的事，下面說），在吉隆坡則還有搭配捷運與電動滑板車。"}]},{"_type":"block","_key":"key-16-wh33y","style":"normal","children":[{"_type":"span","_key":"key-13-3riaw","text":"\n"},{"_type":"span","_key":"key-14-1j3o3","text":"提到交通，不禁想說，我常覺得台灣社會面對問題，常過度責備、貶低自己，例如行人地獄的稱號，我們將對行人友善這件事，拿水準極誇張高的日本來比較😂\n\n"},{"_type":"span","_key":"key-15-u35zs","text":"這裡面包含兩個層面，一個是城市的交通設施設計不獨厚行車，以及汽機車駕駛對尊重行人安全的意識，然而台灣社會卻過度把問題重點放在駕駛不禮讓行人這點，對駕駛的苛責即是將交通問題視為禮儀的道德問題，而非大幅度去改變基礎設施的設計思維。"}]},{"_type":"image","_key":"key-17-slhip","asset":{"_type":"reference","_ref":"01M59MGY8W5HYQE3ZATGFKX253","url":"/_emdash/api/media/file/01M59MGY8W5HYQE3ZATGFKX253.jpg"},"alt":"連結高速公路兩端的空橋（我當時莫名一直想到新竹關埔的那群北七）","caption":"連結高速公路兩端的空橋（我當時莫名一直想到新竹關埔的那群北七）"},{"_type":"block","_key":"key-19-4j6pn","style":"normal","children":[{"_type":"span","_key":"key-18-flqa3","text":"會提到這點是在大馬的體驗，坦白說他們的駕駛並不太在乎路上行人，遇到行人要禮讓？禮讓個屁，還真沒車禮讓過我😆，可是他們城市的交通基礎設施在平衡行車權與行人路權的細節，做的是比台灣好一些，較少有那種高密度的人車交集，必須互搶路的狀況，例如台灣常見騎樓被雜物霸佔，加上本來不該規劃卻規劃停車格的路邊，使得行人冒險走在狹窄馬路邊，與路上的汽機車距離極為靠近，這其中問題更多是設計不良，把行人送去給車撞…\n"}]},{"_type":"image","_key":"key-20-oj19d","asset":{"_type":"reference","_ref":"01M59MGY891TZSY616F93R8DGY","url":"/_emdash/api/media/file/01M59MGY891TZSY616F93R8DGY.jpg"},"alt":"","caption":"騎樓較少見被堆滿雜物，即使放植物盆栽的人也不多"},{"_type":"block","_key":"key-22-csjsa","style":"normal","children":[{"_type":"span","_key":"key-21-3kfwp","text":"不過大馬依舊距離日本那麼適宜行人的水準很遠很遠，我才會說台灣拿日本交通來當比較或目標，實在太苛責自己啦！台灣要改進的地方確實很多，卻也尚且稱不上行人地獄，我去過對行人更不友善的地區🤭"}]},{"_type":"block","_key":"key-25-witlf","style":"normal","children":[{"_type":"span","_key":"key-23-w5xsy","text":"\n"},{"_type":"span","_key":"key-24-0t0zs","text":"總之，徒步旅行就是要安全與樂趣，馬來西亞道路對行人不算友好，但是及格的，加分點是樂趣太多，像是許多老屋的騎樓都別具特色，我到大馬好幾個城市都樂此不疲的四處亂逛，收集不同騎樓的老花磚圖案。"}]},{"_type":"image","_key":"key-26-z3lae","asset":{"_type":"reference","_ref":"01M59MGY9K1KS7PD3SGFADNPKW","url":"/_emdash/api/media/file/01M59MGY9K1KS7PD3SGFADNPKW.jpg"},"alt":""},{"_type":"block","_key":"key-28-69tng","style":"normal","children":[{"_type":"span","_key":"key-27-zstqn","text":"與藏在城市各個角落的彩繪，彩繪多數是政府規劃，也還有人們隨性畫的塗鴉或商家用來做廣告用的彩繪。"}]},{"_type":"image","_key":"key-29-lhdnp","asset":{"_type":"reference","_ref":"01M59MGY9GTQ324XW7C1PJXRW1","url":"/_emdash/api/media/file/01M59MGY9GTQ324XW7C1PJXRW1.jpg"},"alt":"","caption":"藏在奇怪巷子裡的塗鴉 青鳥跟東鹿"},{"_type":"block","_key":"key-31-no7el","style":"normal","children":[{"_type":"span","_key":"key-30-4om41","text":"另外對貓奴而言，馬來西亞超棒的！由於伊斯蘭教法禁止養狗，所以大馬人最常養貓也愛貓，畢竟先知穆罕默德也極愛他名為米埃扎(Muezza)的貓，街頭上也常有被照顧得很好的流浪貓，步行旅遊會經常遇到，我也發現檳城麒麟尾的貓咪比例偏高，麒麟尾貓除了少數是生病，絕大多數都是大航海時代源自印尼的品種，跟著荷蘭人的船隻擴散到各國，歷史上檳城與爪哇的商貿關係密切，可在麒麟尾窺見，今年台南文博會的主視覺也是刻意選麒麟尾貓來紀念台南曾經的貿易歷史。"}]},{"_type":"image","_key":"key-32-jzchh","asset":{"_type":"reference","_ref":"01M59MGY9J9H97CZNQAFVAGVP9","url":"/_emdash/api/media/file/01M59MGY9J9H97CZNQAFVAGVP9.jpg"},"alt":"","caption":"有機會去檳城擼貓之餘，別忘了注意尾巴"},{"_type":"block","_key":"key-36-wl0oh","style":"normal","children":[{"_type":"span","_key":"key-33-fsejy","text":"這次有個遺憾是沒去"},{"_type":"span","_key":"key-35-37vw2","text":"檳城的貓咪海灘 ","marks":["key-34-vke8t"]}],"markDefs":[{"_type":"link","_key":"key-34-vke8t","href":"https://www.instagram.com/p/C_7fEcwzYqy/","blank":true}]},{"_type":"image","_key":"key-37-7jnvy","asset":{"_type":"reference","_ref":"01M59MGY7A2T7TKQA288B627TJ","url":"/_emdash/api/media/file/01M59MGY7A2T7TKQA288B627TJ.jpg"},"alt":"","caption":"馬來愛貓的小細節：攤販攤車上貼著留意貓咪行走的可愛告示"},{"_type":"image","_key":"key-38-jl2yd","asset":{"_type":"reference","_ref":"01M59MGY7G5DNE6AE8H2D2VG5G","url":"/_emdash/api/media/file/01M59MGY7G5DNE6AE8H2D2VG5G.jpg"},"alt":"","caption":"到處都有貓裝飾品，我看到一台白色車甚至裝上白貓耳朵，但來不及拍攝"},{"_type":"block","_key":"key-40-rsxbh","style":"normal","children":[{"_type":"span","_key":"key-39-l9hoe","text":"此外殖民時代的古屋多樣性也是會讓建築迷樂在其中，如果你跟我一樣喜愛 walk trip ，不妨可以去大馬試試"}]},{"_type":"image","_key":"key-41-d9x1f","asset":{"_type":"reference","_ref":"01M59MGY7XJP0N485K209XAWMY","url":"/_emdash/api/media/file/01M59MGY7XJP0N485K209XAWMY.jpg"},"alt":""},{"_type":"image","_key":"key-42-mlpey","asset":{"_type":"reference","_ref":"01M59MGY7YFY6E4VXJ3JS4AVHP","url":"/_emdash/api/media/file/01M59MGY7YFY6E4VXJ3JS4AVHP.jpg"},"alt":""},{"_type":"image","_key":"key-43-zqdw4","asset":{"_type":"reference","_ref":"01M59MGY8HA0VMGK6E8JDZB0ZV","url":"/_emdash/api/media/file/01M59MGY8HA0VMGK6E8JDZB0ZV.jpg"},"alt":""},{"_type":"image","_key":"key-44-miaxa","asset":{"_type":"reference","_ref":"01M59MGY7QZXHMQJGX5RJG0XY1","url":"/_emdash/api/media/file/01M59MGY7QZXHMQJGX5RJG0XY1.jpg"},"alt":""},{"_type":"image","_key":"key-45-k1978","asset":{"_type":"reference","_ref":"01M59MGY84DY0PHXWB9AWEW0FT","url":"/_emdash/api/media/file/01M59MGY84DY0PHXWB9AWEW0FT.jpg"},"alt":""},{"_type":"htmlBlock","_key":"key-46-mklty","html":"[wpb_post_list_table]","originalBlockName":"core/shortcode"}]', '檳城朋友拜託我回台後把旅途體驗分享出來，讓更多台灣人去大馬旅遊，個人討厭走觀光客行程，也不想用旅遊部落客老套的時序類寫法，加上本身有史地、文化研究、飲食消費…的知識存量，所以打算用幾篇不同面向的主題、隨筆的方式來分享這趟大馬旅行', 163, NULL);
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K4QNWK00Z8SWY1RRYDM6Y', 'malaysia-ktm-train-guide', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-07T11:56:29.000Z', '2026-10-19 22:59:59', '2024-10-07T11:56:29.000Z', NULL, NULL, 1, NULL, NULL, 'zh-TW', '01M59K4QNWK00Z8SWY1RRYDM6Y', '馬來筆記 Part.1 行路不難(中)', '{"provider":"local","id":"01M59MGY8F13W8372PYWX91274","alt":"馬來筆記 Part.1 行路不難(中)","width":2560,"height":1981,"mimeType":"image/jpeg","filename":"IMG_20240902_071143-scaled.jpg","meta":{"storageKey":"01M59MGY8F13W8372PYWX91274.jpg"}}', '[{"_type":"block","_key":"key-2-ji9vf","style":"normal","children":[{"_type":"span","_key":"key-1-0uq9v","text":"這趟旅途多次搭乘馬來西亞的火車，具體如何操作我就不寫操作指南了，有 KTMB mobile 的 app 可直接訂票，真的不懂再來推特問我，純粹分享這趟我踩的雷以及有趣的體驗。"}]},{"_type":"block","_key":"key-5-d96pz","style":"normal","children":[{"_type":"span","_key":"key-3-mjyk1","text":"\n"},{"_type":"span","_key":"key-4-ms24p","text":"在部分路線，馬來西亞有所謂 Platinum 列車（另外還有 Gold 、Silver、 Express 三種），大馬的火車價格大約台灣一半，可是班次很少，高階車種的誤點狀況較少，Platinum 是停靠最少、車速最快，Gold 其次，Silver 跟 Express 則是大站小站全都停，所以很慢，如果大城市間移動你希望快一點，選擇 Platinum 跟 Gold ，想去特別的小城市或小鎮，才選擇 Express。"}]},{"_type":"block","_key":"key-7-vxtk7","style":"normal","children":[{"_type":"span","_key":"key-6-o4j73","text":"Platinum 跟另外三種最大的差別就是第一個車廂 Coach A，座椅類似飛機規格，有多媒體播放器並且票價包含供應一份餐飲！前後左右都較寬敞，充電座等設備都有，空間只放 ABC三排椅，其他車廂都是很擠的四排普通椅，"}]},{"_type":"image","_key":"key-8-ejgk1","asset":{"_type":"reference","_ref":"01M59MGY6KYF3ATMS4P4YGEPRS","url":"/_emdash/api/media/file/01M59MGY6KYF3ATMS4P4YGEPRS.jpg"},"alt":"","caption":"Platinum 的尊榮 A車廂在訂位時會顯示金色座椅，喜歡這種撩撥人虛榮心的設計🤣"},{"_type":"block","_key":"key-10-yloc6","style":"normal","children":[{"_type":"span","_key":"key-9-wr5ew","text":"正常來說 Gold 、Silver跟 Express，所有車廂都是四排普通椅，我第一個踩到的雷就在這裡，使用訂位app 時，我看到 Express 的 A 車廂是四排椅，就訂了 9 D 座位，但上車傻眼，只有 ABC 三排椅子，我要坐哪？當下真心無語，難道火車跟飛機一樣會超賣座位嗎？結果這根本是他們 app 錯誤，某些少數的Express 的 A 車廂只有三排椅！app 卻仍舊顯示四排，只是 Express 的三排椅車廂，跟 Platinum 那種比較奢華的服務不同，完全不懂幹嘛拿掉一排椅子，我猜測可能日後所有車種的A 車廂都會升級成 Platinum 那樣，目前是轉換期，這個 app 錯誤我寫文的同時，打開app來看應還沒解決(下圖)， app 中的 Express A 車廂一樣有三排跟四排，為了避免可能沒座位的情況，任何車種的選位記得只選 ABC 的座位！"}]},{"_type":"image","_key":"key-11-i4og4","asset":{"_type":"reference","_ref":"01M59MGY9KN9YXP7J9TA80HXM2","url":"/_emdash/api/media/file/01M59MGY9KN9YXP7J9TA80HXM2.jpg"},"alt":"","caption":"有的Express 顯示三排椅 有的班次顯示四排椅，但實際車相會是三排還四排只有到現場才知道"},{"_type":"block","_key":"key-13-o4g4u","style":"normal","children":[{"_type":"span","_key":"key-12-tash0","text":"跟我一樣買到不存在座位狀況的人有十幾位，車務人員蠻厲害的，幫我安排到後面普通車廂，卻特別找出隔壁沒人坐的座位，讓我一路獨享兩個座椅的寬敞空間，大馬人變通的速度就是很快呀。"}]},{"_type":"image","_key":"key-14-uilp1","asset":{"_type":"reference","_ref":"01M59MGY6HM34E16VGBHRV4HX0","url":"/_emdash/api/media/file/01M59MGY6HM34E16VGBHRV4HX0.jpg"},"alt":""},{"_type":"block","_key":"key-16-cvsgn","style":"normal","children":[{"_type":"span","_key":"key-15-8ufqo","text":"多數列車的C 或D 車廂，還留著英國火車習慣，會有一個小咖啡吧跟小餐桌椅，吃東西的人也會比較多，如果不喜歡食物氣味的朋友請避開這車廂，想體驗則記得走過去看看。"}]},{"_type":"image","_key":"key-17-7tz36","asset":{"_type":"reference","_ref":"01M59MGY8MCNR90HS7NCRJ8593","url":"/_emdash/api/media/file/01M59MGY8MCNR90HS7NCRJ8593.jpg"},"alt":""},{"_type":"block","_key":"key-19-4t0br","style":"normal","children":[{"_type":"span","_key":"key-18-edvg2","text":"第二個雷不是在火車上發生，因為多數票我都在台灣就訂購好了（一個月前可訂票，想搭乘Platinum 的 A 車廂記得早點訂起來），但有幾段臨時想搭乘的路線，在當地我卻發生手機漫遊收不到信用卡驗證簡訊的情況，因此得用購票機操作，購票機不吃現鈔，只支援馬來的電子錢包，還好支援信用卡，搞笑的事來了，大馬機場、捷運、商場、超商、餐廳，幾乎都是靠卡感應式的刷卡機，馬鐵的購票機看起來也是呢，But 它是插卡式讀取！你從黑色外觀根本看不出來有插槽，於是我靠卡在讀卡機螢幕處，支付失敗了十幾次準備放棄時，才突然認出卡跟箭頭的超小icon，忍著暴躁再重新操作一次訂購流程，然後把卡從下面往上插看看，可以了！這什麼鬼設計啦😭 我甚至懷疑這個讀卡機的插槽是不是生產商把上下裝反了，畢竟一般插卡機也多數是由頂端或正面插入，總之當下氣歸氣，事後就覺得自己很白癡很好笑。"}]},{"_type":"image","_key":"key-20-4o9r9","asset":{"_type":"reference","_ref":"01M59MGY8XJXDQHGP8C27E16M5","url":"/_emdash/api/media/file/01M59MGY8XJXDQHGP8C27E16M5.jpg"},"alt":"","caption":"差點把我搞死的購票機長這樣，信用卡插槽正面看不到，放大看才看的到一個超小的圖示"},{"_type":"block","_key":"key-22-lzi9p","style":"normal","children":[{"_type":"span","_key":"key-21-ehlqq","text":"我搭乘南北的主幹線沒遇過誤點，只是車站大廳人潮洶湧，大馬不給隨意進月台，只有在要開車前 15~20 分鐘站務人員會開始剪票放進。而一些支線如往巴生港或黑風洞（Batu Caves），就跟台灣一樣很隨意可以在月台候車，不過我遇到最多妙事與最長誤點也都在支線列車上。"}]},{"_type":"image","_key":"key-23-ojwn6","asset":{"_type":"reference","_ref":"01M59MGY6JRVNEBCD87AB1KZ8Y","url":"/_emdash/api/media/file/01M59MGY6JRVNEBCD87AB1KZ8Y.jpg"},"alt":"","caption":"電訊信號異常暫停行駛"},{"_type":"block","_key":"key-27-v18su","style":"normal","children":[{"_type":"span","_key":"key-24-mj7io","text":"支線列車的座椅配置數量很多，更像是捷運車廂的配置，只有少數車廂是類似傳統火車，你想像跟台灣的區間車一樣就對了，所以搭乘體驗用中國詞彙來形容就是鬆弛感，例如開到一半，廣播說電車訊號異常，於是停下來十分鐘再繼續開，更有遇過，完全沒廣播就莫名停住將近半小時（笑），而我當下卻在心裡慶幸還好車內電燈跟冷氣還有運作，轉頭看四周乘客，沒人動作，"},{"_type":"span","_key":"key-25-q439b","text":"來到大馬幾天，我也漸漸感染了他們那種遇事見怪不怪的自在個性","marks":["strong"]},{"_type":"span","_key":"key-26-js6bs","text":"，如果是在台灣，這時候車廂乘客大概開始交頭接耳、議論紛紛，是個奇怪的時刻，我卻感到內心莫名寧靜，也許漫遊了數天至此，身心在這一刻不再有絲毫身處國外的陌生感，好笑的是十來分鐘後，依舊沒有乘務人員來說明停車原因，這也太鬆弛了吧🤣在台灣已經會被 po 上靠北 xx社團了。"}]},{"_type":"block","_key":"key-29-tl675","style":"normal","children":[{"_type":"span","_key":"key-28-ddonf","text":"又或是我已經喜歡上大馬這個國家了，好的壞的，都是它的一部分，沒道理只因為壞事而生氣。前幾天我才搭乘過 Platinum 的金座椅，體驗了快速無誤點、貼心的車廂服務；區間通勤的列車線，緩慢、誤點、列車異常、沒有服務，有可能是日常就是如此？或是被我撞上的偶然，不管哪一種就都不值得放心上。"}]},{"_type":"block","_key":"key-31-on4vp","style":"normal","children":[{"_type":"span","_key":"key-30-7q8bl","text":"當然，還是時常遇到超乎想像的情景，請看下一張圖，我一踏進這個支線列車的車廂，就忍不住倒退一步，再仔細看一次，確認我沒看錯，這玻璃上是彈孔吧😆 看看車廂地板，沒有血跡、沒有凶器，也沒有屍體，好吧，有屍體我也不是《東方快車謀殺案》（Murder on the Orient Express）裡的名偵探，鐵道推理的情節只在腦袋存在瞬間，我接著平靜的拍幾張照片傳給朋友看，去坐其他車廂了，分享個小知識，歐洲原版的東方快車，因金融海嘯帶來的經濟蕭條而停駛了，先前有機會坐到的鐵道迷很幸運。"}]},{"_type":"image","_key":"key-32-zukil","asset":{"_type":"reference","_ref":"01M59MGY95J1ZYN14Q7P074YJK","url":"/_emdash/api/media/file/01M59MGY95J1ZYN14Q7P074YJK.jpg"},"alt":""},{"_type":"block","_key":"key-35-4saxa","style":"normal","children":[{"_type":"span","_key":"key-33-gx9c6","text":"說到這裡，希望你不要覺得馬來西亞鐵路很爛，狀況多可能是我有點柯南體質，一般人應該不會像我有這麼多加戲的機會（笑）\n"},{"_type":"span","_key":"key-34-p9ua5","text":"馬來西亞火車還給我添了一個小困擾，離開檳城往怡保是我在台灣就預定的路線，我出發前上網多次查詢怡保車站是否有寄物櫃，網路上只看到 2010 以前的討論，說在清真禱告室旁有但已拆除，官方網站上也顯示沒有，我都抱著拖著行李箱到處走的心理準備了，當天出車站我隨口問站務人員，回答竟然是有！藏在很隱密的角落且數量很少，但是有！可以好好更新你們的網站嗎🥹"}]},{"_type":"image","_key":"key-36-ewucr","asset":{"_type":"reference","_ref":"01M59MGY8EHKXA726N0RC6SCVH","url":"/_emdash/api/media/file/01M59MGY8EHKXA726N0RC6SCVH.jpg"},"alt":"","caption":"藏很隱密的寄物櫃數量不多，可放20吋行李箱的約12個，圖片這4個的大小可以放50吋左右的行李箱"},{"_type":"block","_key":"key-38-3h5kw","style":"normal","children":[{"_type":"span","_key":"key-37-v0wsw","text":"最後來分享 Platinum 列車 A 車廂的金座椅，前面有提到整體設計是採用飛機座艙的概念，每個座位都有服務鈴，並有兩位服務員隨侍在這個車廂內，Platinum 只停靠大站，大站之間車程都有一個半小時以上，足夠供餐，餐點的設計就比飛機整套正餐簡單，大致是飲料加點心的下午茶概念，台鐵跟高鐵在餐點上還是較豐富。"}]},{"_type":"image","_key":"key-39-p3p10","asset":{"_type":"reference","_ref":"01M59MGY9KWVY99PXKFGE6YVSM","url":"/_emdash/api/media/file/01M59MGY9KWVY99PXKFGE6YVSM.jpg"},"alt":""},{"_type":"block","_key":"key-42-ajhzt","style":"normal","children":[{"_type":"span","_key":"key-40-cubzz","text":"說來不好意思，個人是易暈體質，暈車暈船暈機你想得到的交通工具我都暈過，從小從不在搭乘交通工具時飲食，飛機的供餐事先可查看，假如沒有誇張想吃的，十次有九次我都請空姐不必為我備餐，給我杯威士忌或調酒讓我好睡就好，因此搭乘 Platinum 我也是婉拒服務員幫我送餐，整趟行程讓我最驚艷的點來了。\n\n"},{"_type":"span","_key":"key-41-tzsqx","text":"當我在車上睡著，距離怡保大約還有 15 分鐘抵達，服務員過來輕輕搖醒我，告知將要抵達我要下車的站！他們竟然有查看每個座位的旅客的目的地是何處，並主動一對一提醒，更讓我驚訝的是她一邊露出空姐式的職業笑容，一邊遞給我一袋熱騰騰的餐盒、零食與瓶裝水，要我帶著吃！真希望航空公司也可以有這種 take out服務！天知道我多少次聞到全飛機充滿機上餐的味道，卻無法吃時有多麼怨念。我很想請她幫我把瓶裝水換成先前聞到的超香咖啡，但臉皮薄還是沒開口。"}]},{"_type":"image","_key":"key-43-7kpo9","asset":{"_type":"reference","_ref":"01M59MGY6S5GR9C2CE9QDVDD1X","url":"/_emdash/api/media/file/01M59MGY6S5GR9C2CE9QDVDD1X.jpg"},"alt":""},{"_type":"block","_key":"key-45-biuz2","style":"normal","children":[{"_type":"span","_key":"key-44-ey2cy","text":"下車後在月台迫不及待開了餐盒，是雞肉仁當口味的陽春版nasi lemak，口味就是超商微波食品那樣中規中矩，真心覺得食物部分太可惜，大馬交通部長應該派人來台灣跟日本考察，若有馬來朋友看到，歡迎把這篇寄給你們備受期待的新任華人部長。"}]},{"_type":"image","_key":"key-46-znw2m","asset":{"_type":"reference","_ref":"01M59MGY8C1231F9GZ0BBXXMS4","url":"/_emdash/api/media/file/01M59MGY8C1231F9GZ0BBXXMS4.jpg"},"alt":"","caption":"可惜 餐盒能更好"},{"_type":"block","_key":"key-49-b1lfm","style":"normal","children":[{"_type":"span","_key":"key-47-cl7u5","text":"大馬的 Platinum 不是最先進的高速車種，金椅子車廂的設備也並不高檔奢華，沿路更沒啥風景，在資金資源受限的狀況下，鐵道服務要怎麼做出高階車廂的差異化？畢竟不是每個國家的鐵道公司都能像日本那樣在硬體上花大錢，做出誇張的奢華感或購買特殊車種，也很少有國家能像日本，有那麼多的自然景觀能恰好跟鐵道路線搭配，更別提各地種類多樣的鐵道便當與各車站都有特色伴手禮，馬來西亞給了我一些答案："},{"_type":"span","_key":"key-48-yhd1r","text":"服務與細節設計，有時候做出一些乘客期待之上、意料之外的小服務，效果勝過於無微不至的服務。","marks":["strong"]}]},{"_type":"block","_key":"key-56-enopo","style":"normal","children":[{"_type":"span","_key":"key-50-janu0","text":"看資料，馬鐵連年虧損，從 1992 至今都虧，不禁讓我想到台灣台鐵也是慘巴巴的連年虧損（1978 至今），票價過去受交通部限制，加上相關養護成本高，使得擺脫虧損一直是努力的目標，在這種狀況下，台鐵也是企圖做出車種的差異化來增加營收，近期開賣的【"},{"_type":"span","_key":"key-52-i0x0i","text":"總統花車","marks":["key-51-yyowr"]},{"_type":"span","_key":"key-53-34yg2","text":"】我就覺得很有意思，台鐵對高階鐵道的想像來自郵輪，更重視硬體氛圍設計與套裝旅遊的搭配，可我認為缺陷也是有的，承接台鐵觀光列車業務的國內旅行社，眼光並沒有放在國際觀光客，許多的設計跟宣傳還是以國內觀光客群，尤其是鐵道迷為主，非常可惜呀！但我搭乘馬鐵 Platinum 列車的 A 級車廂，有半數以上是歐美觀光客！像近期開賣的【"},{"_type":"span","_key":"key-54-gw69i","text":"總統花車","marks":["key-51-yyowr"]},{"_type":"span","_key":"key-55-gkb0q","text":"】，是過往為李登輝總統設計的總統級車廂，這就非常適合拿去日本宣傳，加上本來就有知本、瑞穗溫泉的規劃，整個就是很有吸引日本觀光客的賣點不是嗎？當然如果車廂內服務還能做出意料之外的小服務，我相信會讓乘客無比難忘。"}],"markDefs":[{"_type":"link","_key":"key-51-yyowr","href":"https://www.eztravel.com.tw/activity/railwaysalooncar/","blank":true}]},{"_type":"block","_key":"key-60-c4rqr","style":"normal","children":[{"_type":"span","_key":"key-57-98uff","text":"所以與其嘴砲台鐵不爭氣，我倒覺得台灣社會幾乎沒有集體來想像我們想要怎麼樣的鐵路交通，沒有廣泛認真想過如何讓鐵路服務更好、更好玩，如果說有，可能就是太魯閣號事故後，整個社會對台鐵的究責以及追求安全的呼聲，我得說安全議題絕對重要，但由這個點並沒有擴散出去，形成更全面的議題討論。\n"},{"_type":"span","_key":"key-58-k1s6r","text":"例如，你希望台鐵花東線更安全，是否願意讓他們提高票價，做更多安全維護？是否願意改革現有法令，讓他們從事更多高載量的南北物流或是特殊冷鏈物流？也許一些公路司機會失業，但將現今的國內物流承載方式重新調配，是否能讓台鐵增加收入，同時降低公路上貨運車輛，增加一般公路駕駛的安全？或是增加第三條鐵軌來分流快慢車，提高準點率？\n\n"},{"_type":"span","_key":"key-59-sr036","text":"這些台灣公眾從沒討論，就只有交通專家或鐵道迷們參與，我覺得這才是台灣交通想要變革的阻力，民眾不參與，難道期待只求不功不過的交通官員做出什麼大步改變？"}]},{"_type":"block","_key":"key-62-p37nj","style":"normal","children":[{"_type":"span","_key":"key-61-x8mu5","text":"相比台鐵，大馬鐵路資源絕對沒台灣多，台鐵在特殊車廂車輛的投資更遠比大馬有作為，今年台鐵也公司化成為台鐵公司，公司認為幾年內就可轉虧為盈，在這個組織轉型的契機點，希望台鐵可以好好把握機會。同理，台鐵有一些低成本的商業技巧，可以吸引人們搭乘，例如彩繪列車、復古車款、特定路線的郵輪式旅遊、紀念品，也值得馬來西亞鐵路學習。"}]},{"_type":"block","_key":"key-66-95bc1","style":"normal","children":[{"_type":"span","_key":"key-63-q68tm","text":"寫到這離題太遠了，總之，我覺得如果去馬來西亞旅遊，蠻建議搭看看他們 Platinum 列車 A 級車廂，是一般觀光客很少會去的體驗。\n"},{"_type":"span","_key":"key-64-mluat","text":"假如你是吉隆坡入境，可以嘗試搭乘吉隆坡中央車站，往怡保或太平的一日遊，透早第一班出發，晚上最後一班回吉隆坡；或是吉隆坡入境玩幾天，搭 Platinum 列車到怡保住一兩晚，再搭乘 Platinum 去北海（Butterworth），然後去渡輪口搭船去檳城玩，爾後從檳城直飛回台灣。純個人感受，我覺得旅程都待在大城市吉隆坡很無聊，建議可多往外走走看看。\n\n"},{"_type":"span","_key":"key-65-3geio","text":"P.S.金座椅是我開玩笑的稱呼，別當真"}]},{"_type":"htmlBlock","_key":"key-67-gii5l","html":"[wpb_post_list_table]","originalBlockName":"core/shortcode"}]', ' Platinum 列車 A 車廂的金座椅，整體設計是採用飛機座艙的概念，每個座位都有服務鈴，並有兩位服務員隨侍在這個車廂內，Platinum 只停靠大站，大站之間車程都有一個半小時以上，足夠供餐，餐點的設計比飛機整套正餐簡單，大致是飲料加點心的下午茶概念', 97, NULL);
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K4VXSA8VYD6TRHTETHB09', 'malaysia-street-hospitality', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-07T13:12:55.000Z', '2026-10-19 22:59:59', '2024-10-07T13:12:55.000Z', NULL, NULL, 1, NULL, NULL, 'zh-TW', '01M59K4VXSA8VYD6TRHTETHB09', '馬來筆記 Part.1 行路不難(下)', '{"provider":"local","id":"01M59MGY8QP21VJAVNBJD36B9B","alt":"馬來筆記 Part.1 行路不難(下)","width":1920,"height":2560,"mimeType":"image/jpeg","filename":"IMG_20240903_153441-scaled.jpg","meta":{"storageKey":"01M59MGY8QP21VJAVNBJD36B9B.jpg"}}', '[{"_type":"block","_key":"key-3-01lex","style":"normal","children":[{"_type":"span","_key":"key-1-uz7rm","text":"在大馬徒步旅行最大阻礙莫過於天氣炎熱，大城市還好，購物商場非常多，超商的密度也蠻高，有冷氣的咖啡廳也不少，時常進去吹吹冷氣修整一下再上路，但若是去小城市或偏僻點的地方，上面的商場、超市、咖啡廳都很少見，會熱到你反覆懷疑人生。\n\n"},{"_type":"span","_key":"key-2-b6626","text":"我強力推薦去大馬一定要準備 Biore 的涼感濕紙巾（要選包裝上有 cool 小字樣的版本，沒 cool 字樣的沒用），多帶個兩包，你一定會感謝我，不要在台灣買身體降溫噴霧，那完全沒用，請抵達大馬後，在機場藥妝店，直接買兩瓶當地 Koolfever Spray 這個牌子的衣物涼感噴霧（下圖），裡面薄荷腦的成份高、酒精成分低所以不用怕過敏，只要你覺得身體有要燥起來，就趕緊往衣服前後噴好噴滿，相信我，這真的夠涼而且才能在大太陽曝曬下維持較長時間！台灣藥妝店賣的幾個牌子，都是噴上去瞬間有感，走在高溫環境，大概一分鐘就毫無效果了，純粹是智商稅… 不知道為何沒看過旅遊部落客介紹 Koolfever Spray 這個降溫神器，我準備搭機離開大馬時，還特地帶了兩罐回台，你看有多愛它（有擅長做網購進口的推友可留意，這是一個超適合引進台灣的商品）。"}]},{"_type":"image","_key":"key-4-37zyj","asset":{"_type":"reference","_ref":"01M59MGY9CPW7Z8CAGV5Z0MYDJ","url":"/_emdash/api/media/file/01M59MGY9CPW7Z8CAGV5Z0MYDJ.jpg"},"alt":""},{"_type":"block","_key":"key-6-4apig","style":"normal","children":[{"_type":"span","_key":"key-5-37kx6","text":"也許是我經常跑去沒觀光客會去的地方，就常被當地人拉著攀談或餵食😂 可能你會好奇跟大馬人可以聊什麼？聊天通常語言能力要好，其次是要有話題可以一直談論，我語言能力算蠻不錯，不過馬來西亞的語言能力所重視的面向，跟我們習以為常的很不同，下一篇會再細說，經過跟幾個路人嘗試後，我很快就掌握讓任何大馬人會喜歡跟你一直聊下去的的話題 - 談論食物！"}]},{"_type":"block","_key":"key-8-1ngjs","style":"normal","children":[{"_type":"span","_key":"key-7-nwnnx","text":"跟美國人 small talk 的禁忌一樣，盡量不要跟大馬人談論政治，尤其是非華裔，因大馬人的政治立場跟種族矛盾是高度重疊的密集雷區，尤其跟你族裔不同時，很容易讓人不想跟你談下去，但面對大馬華人，就無所謂，許多馬華的叔叔阿姨們，可是對台灣政治瞭若指掌，馬華處在政治弱勢，面對台灣人，也較願意分享大馬社會下隱藏的不平等與不自由的點，但一般來說，除非很熟，否則人們還是不願意跟外國人說自己國家不好的點。"}]},{"_type":"image","_key":"key-9-s3hmu","asset":{"_type":"reference","_ref":"01M59MGY6KWNMW445D7RD6MGXJ","url":"/_emdash/api/media/file/01M59MGY6KWNMW445D7RD6MGXJ.jpg"},"alt":"","caption":"檳城咖哩麵神人六叔與身穿挺基隆罷樑 T-shirt 的我😆，六叔是已故的施明德鐵粉，其素食咖哩麵真是絕品美味，跪推"},{"_type":"block","_key":"key-11-vn0fw","style":"normal","children":[{"_type":"span","_key":"key-10-42s23","text":"綜合來說，無論跟哪一種大馬民族開啟對話，聊食物就成為門檻最低、效果最好的話題！其次則是誇讚大馬，第三則是音樂。大馬人對自己食物是又熱愛又自豪，當被攀談時，話題就可以如下面範例這樣開始（多數是英語夾雜台語跟中文，我打成中文，方便讀者閱讀）"}]},{"_type":"block","_key":"key-13-9nl33","style":"blockquote","children":[{"_type":"span","_key":"key-12-1b9hr","text":""}]},{"_type":"block","_key":"key-15-yzri5","style":"blockquote","children":[{"_type":"span","_key":"key-14-e337u","text":""}]},{"_type":"block","_key":"key-17-svutx","style":"blockquote","children":[{"_type":"span","_key":"key-16-6qm1w","text":""}]},{"_type":"block","_key":"key-20-ym4jb","style":"normal","children":[{"_type":"span","_key":"key-18-wabaj","text":"\n"},{"_type":"span","_key":"key-19-whpzi","text":"你會發現無論對方問什麼，我都把回答導引到馬來食物，記得要具體說出食物的名稱😆 常常聊著聊著，對方就帶我去他推薦的店，或是給我美食情報，又或是為我講解馬來食物的料理方式、吃的方法…等等，更有幾次是邊聊，對方邊轉頭跟旁邊小販點餐，說著一些我聽不懂的詞彙，似乎是交代他們要怎麼特別製作調味，接著把餐點塞給我吃，並一邊解釋如何吃，被陌生人餵食的經驗實在很特別，讓我想起怕你餓的台灣阿嬤，與台灣擔心怠慢客人的熱情周到不同，當你表露對大馬食物的由衷喜愛，大馬人就會把你當朋友般分享，而不僅僅是一個外國人、觀光客或過路人！非常感謝這次一路上偶遇、關照我這吃貨的大馬朋友們。"}]},{"_type":"image","_key":"key-21-i0elq","asset":{"_type":"reference","_ref":"01M59MGY7HQRBCN80ADEFNPN20","url":"/_emdash/api/media/file/01M59MGY7HQRBCN80ADEFNPN20.jpg"},"alt":"","caption":"被陌生印度小哥請的飲料"},{"_type":"block","_key":"key-23-7fkij","style":"normal","children":[{"_type":"span","_key":"key-22-ekrqh","text":"如果你本身是個 small talk 高手，我相信不管在什麼國家，應該都能跟當地人相處的很好，當然啦，不管別人怎麼對待，我們終究是外國人，一些禮儀還是要遵守，我覺得有三點比較要注意"}]},{"_type":"block","_key":"key-27-zrxeb","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-24-kxrhm","text":"茶餐室 (Kopitiam) 或是巴剎（市場）邊的餐桌椅，當你坐下來後，就會有茶水小販過來問你要喝什麼，記住，無論你想不想喝，只要坐下來就一人要點一杯喝的，我本身很不愛喝飲料，在台灣也是一年喝不到幾次手搖飲的人，但在這裡，點茶水是必要的消費習俗，茶水看場合也會有水準差別，馬來西亞國內也經常在討論這習俗是否合宜，因為有些小攤的茶水品質過於低劣，但又不得不點，實在惱人。\n\n"},{"_type":"span","_key":"key-25-emf7f","text":"既來之則安之，後來我也習慣並找到其中樂趣，像我們去西式餐酒館，享受的不只是吃食，還有與之搭配的酒飲，我嘗試在茶水小販過來詢問時，先告知他我點了什麼餐點，請他幫我推薦最適合搭配的茶水，像把他當侍酒師使用🤣，於是品嚐到滷肉配菊花茶、炒粿條配涼茶、福建麵配龍眼茶、乾粉炸料配紅豆冰沙，當然也有被推薦過很雷的飲料，我自己還嘗試搭配過福建蝦麵配冰杏仁茶（這很搭❤️）、叉燒雲吞麵配虎咬獅、潮州粥配印度奶茶、白咖哩麵配甘蔗汁…等，只要懂得怎麼跟茶水小販打交道，點茶水這件事也成為吃食體驗的加分項。\n\n"},{"_type":"span","_key":"key-26-ouxdj","text":"小知識：有些茶水單會有紅毛水這個選項，即是蘇打水、汽水"}]},{"_type":"image","_key":"key-28-afrdv","asset":{"_type":"reference","_ref":"01M59MGY877KT36D4HY6NJKTKZ","url":"/_emdash/api/media/file/01M59MGY877KT36D4HY6NJKTKZ.jpg"},"alt":""},{"_type":"block","_key":"key-30-nzaoi","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-29-11rin","text":"廟宇，無論是中式廟宇、清真寺或興都廟，若進去內部後，不要把它當成網紅景點在那邊吵鬧擺拍，中式廟宇對進出比較寬鬆，清真寺與印度廟則通常有開放參觀的時間，不要冒冒然就亂闖，進去也有服儀穿著的習俗，可上網先做做功課。"}]},{"_type":"block","_key":"key-34-h1f41","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-31-d5ssr","text":"大馬抽菸者指南：馬來西亞的禁菸規定非常嚴格，官方的理想是能做到類似新加坡、日本，效果也確實是有的，煙草大廠Philip Morris(美股 PM) 這幾年在大馬的紙菸銷售量下滑的非常厲害，不過一次性電子菸的銷量卻同時大增，並且消費族群有往更年輕化發展，目前多數許可電子菸的國家都有這種現象，明明是為了降低年輕人吸菸，可是禁止紙菸影響不大，反倒是開放電子菸對年輕人吸引力更高。\n\n"},{"_type":"span","_key":"key-32-utley","text":"總的來說，不想給大馬官方造成困擾，所以接下來我隱晦地講，法規來講，大馬可以說處於全面禁菸的程度，只有特別設置的吸菸區才可以，但官方規劃的區域少之又少，因此還是很多人在不可抽菸的場所抽菸，此外，不同城市的執法力度差異很大，越是小地方，執法力度越低，守法意識也越低，也就產生一種奇妙的狀況，法規很清楚，可是執法與守法的範圍卻極度模糊，但我總歸了五個“絕對不要抽菸“的地點，包括電子菸，就是學校附近、廟宇周遭、餐廳旁、交通設施、政府機構附近。\n\n"},{"_type":"span","_key":"key-33-jnwre","text":"首先不要帶菸跟電子菸入境，很容易被查沒罰款，在當地超商買就可，如果你本身有很高的抽菸需求，住宿時請先確認旅館有設置吸菸區或吸菸室，然後買個一次性的電子菸，抽起來比較不起眼，並且只要不是上面五個地點，偷偷抽不太會有人管你，好了我就說到這😌還是請吸菸朋友（盡可能地）遵守當地法規，不丟台灣人的臉。"}]},{"_type":"block","_key":"key-45-d6a2s","style":"normal","children":[{"_type":"span","_key":"key-35-t20of","text":"\n"},{"_type":"span","_key":"key-36-7ua8x","text":"旅途中，一位意外很談的來的馬來朋友曾跟我說：「"},{"_type":"span","_key":"key-37-sjq6i","text":"大馬社會包容而且多元，並不自由","marks":["strong"]},{"_type":"span","_key":"key-38-30okq","text":"」，在我看來並不盡如此，中國有所謂潛規則，源自於 CCP錢權的基礎，隱性的箝制多數人，也讓多數人自我限制。\n"},{"_type":"span","_key":"key-39-0x7ji","text":"我看見的馬來西亞是多民族治理的情境，讓他們在價值上，必須首要先追求多民族的包容、凝聚、團結，包括前述法規強硬與執法彈性的落差，根本原因也是多民族治理力道的困難，因此大馬也是個自由民主的政體，如同新加坡也是，可能跟我們習以為常的不太一樣，但絕對不是中國那樣充滿極權特徵與叢林法則的社會風範，大可放心。\n\n"},{"_type":"span","_key":"key-40-jm50g","text":"順帶一提，上述大馬朋友經營一家手工藝/藝術品/文創商品的選物店 Timura @ Armenian （"},{"_type":"span","_key":"key-42-liwa5","text":"google map","marks":["key-41-tgr1c"]},{"_type":"span","_key":"key-43-uqpw0","text":"），是個親切健談的姐姐，有去檳城的朋友，歡迎去找她喝杯茶、買點別緻的伴手禮、聽聽檳城與大馬的故事。隔壁的名香泰餅家（Ming Xiang Tai），美味的蛋塔、咖央餃、雞肉叉燒包務必試試，台灣也有的老婆餅與蛋黃酥大可不必了。\n\n"},{"_type":"span","_key":"key-44-o00kx","text":"所有內容純粹為個人旅途的觀察、對談後的體悟，若有良性的見解歡迎指教，若要政治意見筆戰，恕不奉陪。"}],"markDefs":[{"_type":"link","_key":"key-41-tgr1c","href":"https://maps.app.goo.gl/PgvAnfP7sXLH1NqSA","blank":true}]},{"_type":"htmlBlock","_key":"key-46-jbv2y","html":"[wpb_post_list_table]","originalBlockName":"core/shortcode"}]', '被陌生人餵食的經驗實在很特別，讓我想起怕你餓的台灣阿嬤，與台灣擔心怠慢客人的熱情周到不同，當你表露對大馬食物的由衷喜愛，大馬人就會把你當朋友般分享，而不僅僅是一個外國人、觀光客或過路人！', 95, NULL);
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K504TRFVT8RE5NX8BJSHF', 'malaysia-multiracial-code', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-08T11:45:07.000Z', '2026-10-20T04:14:12.855Z', '2024-10-08T11:45:07.000Z', NULL, NULL, 5, '01M5BR8JX0MSB9E67H3F4XCDZR', NULL, 'zh-TW', '01M59K504TRFVT8RE5NX8BJSHF', '馬來筆記 Part.2 折衷的共存智慧', '{"id":"01M59MGY7MENQB8JM2W341G5A5","provider":"local","filename":"IMG_20240831_093846-scaled.jpg","mimeType":"image/jpeg","width":1920,"height":2560,"alt":"馬來筆記 Part.2 折衷的共存智慧","meta":{"storageKey":"01M59MGY7MENQB8JM2W341G5A5.jpg","caption":null,"blurhash":null,"dominantColor":null}}', '[{"_type":"block","_key":"key-2-87pyl","style":"normal","children":[{"_type":"span","_key":"key-1-tiq6v","text":"出發之前，我對馬來西亞眾所皆知的多種族多元文化已經有心理準備，實際抵達後，遠比書籍或網上資料，有更強烈的衝擊與感觸。"}]},{"_type":"block","_key":"key-4-5cqpc","style":"normal","children":[{"_type":"span","_key":"key-3-02311","text":"文章篇幅很長，下面是AI生成的摘要聲音檔，可聽聽有興趣再讀全文"}]},{"_type":"embed","_key":"key-5-6x77z","url":"/_emdash/api/media/file/01M59MGY9E2FGZER6Y0BDW2H3W.mp3","provider":"audio","html":"<figure class=\"wp-block-audio\"><audio controls src=\"/_emdash/api/media/file/01M59MGY9E2FGZER6Y0BDW2H3W.mp3\"></audio></figure>"},{"_type":"block","_key":"key-8-seuia","style":"normal","children":[{"_type":"span","_key":"key-6-5w3os","text":"\n"},{"_type":"span","_key":"key-7-ny9re","text":"大馬經常看到不同族群之間的差異，可是下一刻又看到族群沒有差別的點，例如當我在檳城的觀音廟時，廟宇與周邊巷弄的格局，都有身處彰化或台南古都的感受，若是真的拿檳城觀音廟與彰化觀音亭做座標參照，就會發現非常多相似處，觀音廟都處在最起初的城區範圍的正中心點，彰化關帝廟的位置，在檳城出現的是印度廟，彰化孔廟的位置在檳城則是基督教堂，鄰近還有清真寺與福德祠，有興趣可嘗試將地圖旋轉做空間參照，大馬對信仰的需求不分族裔，在有限的街區空間，各信仰各安其所的共存，所以這條街又稱為「和諧之街」。"}]},{"_type":"image","_key":"key-9-7hmkk","asset":{"_ref":"01M59MGY9K9WEHR3V36DXANHAW","url":"/_emdash/api/media/file/01M59MGY9K9WEHR3V36DXANHAW.jpg"},"caption":"檳城與彰化，城市早期的規劃 都以觀音亭作為中心點"},{"_type":"block","_key":"key-11-0tuzo","style":"normal","children":[{"_type":"span","_key":"key-10-jqz27","text":"走進了附近的茶餐室(kopitiam)，看到多族裔不分信仰一起擠在茶餐室用餐，一開始會以為雞飯、雲吞麵可能華人愛吃，海南麵包與咖哩雞可能是印度裔，nasi lemak 則是馬來人，實際上全然不是這麼一回事，信仰也許無法共享，但在飲食上，除了伊斯蘭信仰者必須遵守的飲食戒律，大馬人不分族裔，只要是好吃的都會大口吃下。"}]},{"_type":"image","_key":"key-12-tsus6","asset":{"_ref":"01M59MGY97F072W2VGQ5EHYEH3","url":"/_emdash/api/media/file/01M59MGY97F072W2VGQ5EHYEH3.jpg"},"caption":"馬來西亞有多愛nasi lemak，從肯德基也不得不賣就看的出來"},{"_type":"block","_key":"key-14-ar90a","style":"normal","children":[{"_type":"span","_key":"key-13-1ldi5","text":"馬來西亞朋友很喜歡推薦外國人吃辣死你媽（nasi lemak），辣死你媽實際上多數並不辣，是一種椰漿飯，搭配炸江仔小魚與叄巴辣醬 （sambal tumis），這也是一個多民族共享的料理，你可以在吉隆坡由華人掌廚的 Village Park 餐廳，吃到清爽卻奇香無比的椰漿飯"}]},{"_type":"image","_key":"key-15-pol5p","asset":{"_ref":"01M59MGY99QTQJQ5J56ADYXFS2","url":"/_emdash/api/media/file/01M59MGY99QTQJQ5J56ADYXFS2.jpg"}},{"_type":"block","_key":"key-17-kpr4b","style":"normal","children":[{"_type":"span","_key":"key-16-ac1vr","text":"也可以清晨時在馬來婦女開的街邊檔口，吃到辣到你想叫媽的叄巴辣醬（sambal tumis），印度廟附近的 nasi lemak 則增添些許印度香料飯（nasi briyani）的風味，印度風味的配菜比例高，如坦都里烤雞與脆餅。我個人則最喜歡 nasi lemak 搭配仁當牛肉或亞參蘇東（asam sotong），然後再點上一塊馬來炸雞，熱量爆表這種事來馬來西亞就請忘了吧。"}]},{"_type":"image","_key":"key-18-x4jce","asset":{"_ref":"01M59MGY995GGGSP086HTS79VF","url":"/_emdash/api/media/file/01M59MGY995GGGSP086HTS79VF.jpg"}},{"_type":"block","_key":"key-21-t5hue","style":"normal","children":[{"_type":"span","_key":"key-19-we82b","text":"\n"},{"_type":"span","_key":"key-20-qam48","text":"同一道菜，不同族裔有不同的側重，華人在意米的烹煮，馬來人首重辣醬的層次感，印度人則更希望能在其中吃到熟悉的傳統風味，多樣性的交融就是馬來西亞食物最有趣之處，例如前述Village Park 的華人老闆烹煮椰漿飯的秘訣是連蒸三回逐次添料（下圖），這種手法在印度香料飯（nasi briyani）就常被使用，是創始人自己揣摩出來的或確實跟印度料理借鏡，不得而知。我還見過不少馬來人經營的 nasi lemak ，裡面放的不是最常見的水煮蛋或煎蛋，而是中式鹹蛋！可惜我當時已經飽到絲毫吃不下，否則很想嚐嚐那是什麼滋味。"}]},{"_type":"image","_key":"key-22-ui86e","asset":{"_ref":"01M59MGY8TM94ZA22WHF1GQP7M","url":"/_emdash/api/media/file/01M59MGY8TM94ZA22WHF1GQP7M.jpg"}},{"_type":"block","_key":"key-24-m1t98","style":"normal","children":[{"_type":"span","_key":"key-23-x48zk","text":"即便不同族裔的料理人有不同風味，客群往往不會因此受限，大馬人味覺的偏好光譜實在很寬，美味的店家不管什麼族群的客人都有，大馬人對待不同飲食文化的態度是非常平等的（當然政治上未必平等），這點我覺得台灣社會值得學習，我們談論飲食時，還是常不自覺帶著社經階層的刻板印象。"}]},{"_type":"block","_key":"key-29-9hlp9","style":"normal","children":[{"_type":"span","_key":"key-25-t0a96","text":"料理的思維在不同族裔，也經常有異曲同工之妙，例如薄餅是大馬所有民族都有各自的料理方式（可翻閱"},{"_type":"span","_key":"key-27-s28ve","text":"陳靜宜老師的著作","marks":["key-26-o6d7r"]},{"_type":"span","_key":"key-28-jpos4","text":"），華人的福建蝦麵以濃郁的蝦味湯頭聞名，我發現馬來人料理也有一個 mee udang 的蝦麵料理，兩者沒有直接關係，但是料理創作的思路非常雷同，咖哩麵、雞飯（nasi ayam）也是同樣的例子，不同族裔做出來的口味也截然不同，各有其精妙之處，所以來到檳城，除了各種茶餐室，印度裔的嘛嘛檔（mamak）也一定不能錯過。"}],"markDefs":[{"_type":"link","_key":"key-26-o6d7r","href":"https://www.books.com.tw/products/E050027426?sloc=main","blank":true}]},{"_type":"image","_key":"key-30-jin7s","asset":{"_ref":"01M59MGY9H5RQ6Q36YYNZ2RM6W","url":"/_emdash/api/media/file/01M59MGY9H5RQ6Q36YYNZ2RM6W.jpg"},"caption":"左為mee udang  右為福建蝦麵 可看出調味方式全然不同"},{"_type":"block","_key":"key-33-2xw5b","style":"normal","children":[{"_type":"span","_key":"key-31-mwb64","text":"路途中的感觸："},{"_type":"span","_key":"key-32-qj060","text":"在大馬，你以為是界線的地方，其實只是你認知的界線，你見到界線的地方，也許明天就發現新的事物輾過去，讓先前的界線毫無痕跡。","marks":["strong"]}]},{"_type":"block","_key":"key-36-b9qux","style":"normal","children":[{"_type":"span","_key":"key-34-3misv","text":"\n"},{"_type":"span","_key":"key-35-lzll0","text":"最明顯的界線被改變來自於自己的變化，才一兩天，我講話也開始中文台語英語夾雜，本來三種語言我都算道地，混在一起夾雜講，我感覺自己語感都錯亂了，聽到自己口中說出類似晶晶體的話，還有種難以言喻的羞恥感。有時候，談話的對象還夾雜馬來語或廣東話，但他沒意識到，對話時，我必須講的同時判斷對方反應，經常一句話還沒講完，發現對方不懂，就要快速切換另一個語言的詞彙，來讓對方理解我意思，當我切換越快越順暢，他越覺得我好聊而且語言能力好，我甚至被逼著偶爾冒出日文，可是即便一句話我夾雜三個語言，但對方毫不在意。"}]},{"_type":"block","_key":"key-38-gwoqu","style":"normal","children":[{"_type":"span","_key":"key-37-7b6fg","text":"這打破我過往的語言習慣，大馬語言能力好的基本標準，是語系的廣度與詞彙的包容度，而不是發音的精準或語彙的深度，作為標準話的馬來語原先就是拼裝而來，在不同族群的使用下，相同的語彙固然多，但各族群把自己語言的更多慣用語夾藏進去或挪用，讓馬來語變得更具包容與多元性（當然也更複雜了），隨著不同文化背景的人們頻繁相互流動、交融和交流，所有的文化界線都變得越來越難以辨識。"}]},{"_type":"block","_key":"key-40-7x56b","style":"normal","children":[{"_type":"span","_key":"key-39-75zcy","text":"福建移民是大馬華人中最多的，普遍都會說福建話，不過台灣台語跟馬來西亞的福建話差異不小，北部的檳城福建話向馬來語的借用語較少，我們聽起來就較好懂，但越往中部南部借用語越多、發音腔調越重，甚至混進潮州、客家或馬來語，聽起來就極吃力，對凡事喜歡追根究底的我來說，讓自己放輕鬆接受這些交融後的語言產生的不解，充滿好奇心卻無法被滿足，著實難受（有些詞彙大馬人也不知道從何處用過來，或為何這樣使用，多數時候就只是習慣這樣說，或聽人這樣說過就學起來用），可能得真格去當地長時間進行田野調查，才能更清晰的梳理出脈絡。"}]},{"_type":"block","_key":"key-42-ejwv3","style":"normal","children":[{"_type":"span","_key":"key-41-b7oa9","text":"土生華人 (Peranakan) ","marks":["strong"]}]},{"_type":"block","_key":"key-44-0shaa","style":"normal","children":[{"_type":"span","_key":"key-43-7ylq4","text":"事實上，即便是如今大馬的五大族群中，馬來西亞華人也並非是那麼純粹華味，像是還有土生華人、土生葡萄牙人這些，土生華人 (Peranakan) 詞意是由馬來語的 Anak (本地的) 與 Child (孩子) 組成，是指馬來本地人與外國人通婚後的後裔，由於族群混合的多樣性，土生華人只是一個模糊的詞彙，像是菲律賓就有極多不同的混血族裔的稱呼與分支，例如麥士蒂索人 Mestizo 就包含華裔混血、西班牙裔混血、阿拉伯裔混血…等等。"}]},{"_type":"block","_key":"key-47-tc7p6","style":"normal","children":[{"_type":"span","_key":"key-45-puxus","text":"\n"},{"_type":"span","_key":"key-46-cvwtc","text":"在馬來的土生華人 (Peranakan) 中，最特色鮮明的莫過於峇峇娘惹(Babas Nyonyas)，不過若釐清血緣與認同，可以說峇峇娘惹 (Babas Nyonyas) 都是土生華人 (Peranakan)，但不是每個土生華人 (Peranakan) 都是峇峇娘惹 (Babas Nyonyas) 人，以下簡稱娘惹人，娘惹人也並非馬來專屬，泰國、緬甸、印尼、新加坡等地也有。"}]},{"_type":"block","_key":"key-52-xxfzx","style":"normal","children":[{"_type":"span","_key":"key-48-sd9iz","text":"娘惹人是少數族裔，並不是我們刻板印象中文化落後的少數民族，家族成員有的甚至可溯源到十代以上，祖輩遠在荷蘭殖民前就定居在馬來、爪哇，取了當地女性為妻，生下的男孩稱為「峇峇」，女孩則名「娘惹」，默默累積家族財富，太田泰彥描述到在英國取代荷蘭統治麻六甲等地後，峇峇娘惹來到最顛峰的財富盛世，富裕促進了對消費文化品味的精雕細琢，關於娘惹人的興衰與文化特徵，有興趣多了解推薦日本記者太田泰彥寫的【"},{"_type":"span","_key":"key-50-rd6ho","text":"發現峇峇娘惹","marks":["key-49-ny4ky"]},{"_type":"span","_key":"key-51-9vtg8","text":"】。"}],"markDefs":[{"_type":"link","_key":"key-49-ny4ky","href":"https://www.books.com.tw/products/0010971469?srsltid=AfmBOooOdcH9MrBvf664q78Ks_UllXm1VtTCJO-Jk-IsE2SL-NFN_v4m","blank":true}]},{"_type":"block","_key":"key-54-uiuv5","style":"normal","children":[{"_type":"span","_key":"key-53-awgl1","text":"我對娘惹族群充滿好奇，很大一部分來自他們的文化產物之獨特品味，已經顯著地與祖輩的家鄉中國，有很高的歧異性，當一個移民或混血的社群與原生中國的社群，在文化發展走向不同方向時，這還能稱為同一個民族嗎？巔峰時的娘惹人是否有自覺自己在消費與文化上的高度，已經遠超過當時的中國？當這個自覺意識與財富自由的雙重條件出現時，他們還會維持對祖籍的國族認同嗎？他們之中有人經歷過對祖國幻想的破滅嗎？"}]},{"_type":"block","_key":"key-56-ekr1s","style":"normal","children":[{"_type":"span","_key":"key-55-l6oow","text":"好奇感的第二部分也源自參照台灣人的處境，有許多人即使祖上不是 1949 遷徙來台，是在台灣落地生根數代，有的長達兩百年以上，例如號稱祖先來台至今十代的連勝文，但還是抱著落葉歸根的不切實際，又例如某位明明是在台灣好幾代的台灣人政客，卻將自己的名字改為崑崙山上的一株小草？他祖籍也跟崑崙山脈所處的省分八竿子打不著！不僅這群別有居心的政治人，我很納悶這群成天喊著落葉歸根的台灣民眾，會不會是對自身移民文化的不自信與充滿刻板印象？是什麼區分了芋頭跟番薯？"}]},{"_type":"block","_key":"key-59-bauu7","style":"normal","children":[{"_type":"span","_key":"key-57-44rbf","text":"對峇峇娘惹的諸多好奇探索與疑問，也引發我反覆再確認自己的認同歸於何處？政治光譜的我是 1450，文化認同跟族群認同上，我算是驕傲的土生台灣人吧 (笑)。\n\n"},{"_type":"span","_key":"key-58-gf1yi","text":"以往學術中有許多關於離散人群 (diaspora) 的認同討論，在研究 18、19 世紀東南亞，都以海外華人作為含糊的描述主體，其中各族裔族群較欠缺深刻研究，偏偏娘惹人社群歷來就是低調、封閉，藏身在馬來人、華人中，神秘的色彩讓外人很難有機會接觸到他們，這趟旅程我積極地跟路人攀談，某個程度也是想碰碰運氣，看看是否能遇到明確族裔認同的的娘惹人，可惜沒直接遇到，不過遇到一位檳城朋友，其 70 幾歲的娘惹奶奶，是製作傳統娘惹服裝與珠繡鞋的老師傅，他願意在我下次去檳城時會幫忙引見，希望下一趟有機會能認識更多。"}]},{"_type":"block","_key":"key-61-t7071","style":"normal","children":[{"_type":"span","_key":"key-60-makog","text":"身處大馬，有多熟悉感，卻也時常被陌生感挑戰，像在伊斯蘭博物館看文物，突然看到聲援加薩的童畫特展，才被提醒到這是一個伊斯蘭信仰，且與我對以哈戰爭的政治立場截然相反的國家，同樣伊斯蘭兄弟，新疆維吾爾人不也是伊斯蘭嘛，所以與其說是盲目的宗教信仰，更多還是國家政治的選擇。"}]},{"_type":"image","_key":"key-62-09e1a","asset":{"_ref":"01M59MGY8Q653ESNNM64QCG9D1","url":"/_emdash/api/media/file/01M59MGY8Q653ESNNM64QCG9D1.jpg"}},{"_type":"image","_key":"key-63-hm7lf","asset":{"_ref":"01M59MGY9FGQ41PQ2AQ2C919PK","url":"/_emdash/api/media/file/01M59MGY9FGQ41PQ2AQ2C919PK.jpg"}},{"_type":"block","_key":"key-65-z4rs7","style":"normal","children":[{"_type":"span","_key":"key-64-md3bo","text":"又或是正當我心滿意足吃完 Nasi Kandar 在散步，迎面就看到紅通通的招牌「馬來西亞一代一路研究所」，朝貢體系是前殖民時代的古中國維持東南亞影響力的方式，一代一路是中共試圖重建現代版本的朝貢體系，好喔，身為一個外國人沒資格說什麼，只是感受到這國家政府，對內淡化華人影響與強化馬來認同，對外有利益之處，也毫不猶豫親中，同時也跟美國討好處，在大國博弈間求生存，馬來西亞數百年的歷史一直是如此走過來的，這樣一個國家會輕易變成中共一代一路的魁儡嗎？我是存疑的"}]},{"_type":"image","_key":"key-66-415mn","asset":{"_ref":"01M59MGY7ZMY21V8RTCG1B9BCW","url":"/_emdash/api/media/file/01M59MGY7ZMY21V8RTCG1B9BCW.jpg"}},{"_type":"block","_key":"key-68-4wown","style":"normal","children":[{"_type":"span","_key":"key-67-v8tfj","text":"無論如何，馬來西亞就是這麼複雜又迷人。"}]},{"_type":"htmlBlock","_key":"key-69-n6rxw","html":"[wpb_post_list_table]"}]', '同一道菜，不同族裔有不同的側重，華人在意米的烹煮，馬來人首重辣醬的層次感，印度人則更希望能在其中吃到熟悉的傳統風味，多樣性的交融就是馬來西亞食物最有趣之處', 87, 'https://flavorinsight.com/wp-content/uploads/2024/10/dq4sq4m28pi5d3.mp3
3397440
