');
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K54C4VDFVFC38HTRN8H38', 'penang-tainan-wok-hei', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-09T09:40:53.000Z', '2026-10-20T04:11:53.542Z', '2024-10-09T09:40:53.000Z', NULL, NULL, 6, '01M5BR4ANF704KDP15DVPWFQXS', NULL, 'zh-TW', '01M59K54C4VDFVFC38HTRN8H38', '馬來筆記 Part.3 從檳城看見台南的府城味', '{"id":"01M59MGY6Z8MGY1ZBCKPW316CK","provider":"local","filename":"IMG_20240829_220958-scaled.jpg","mimeType":"image/jpeg","width":2560,"height":1920,"alt":"馬來筆記 Part.3 從檳城看見台南的府城味","meta":{"storageKey":"01M59MGY6Z8MGY1ZBCKPW316CK.jpg","caption":null,"blurhash":null,"dominantColor":null}}', '[{"_type":"block","_key":"key-2-qfwsn","style":"normal","children":[{"_type":"span","_key":"key-1-xp92s","text":"下面音訊為本篇內容使用Notebook LLM的AI生成"}]},{"_type":"embed","_key":"key-3-grxbu","url":"/_emdash/api/media/file/01M59MGY9QE5VB6FW2ZWQZGGT7.mp3","provider":"audio","html":"<figure class=\"wp-block-audio\"><audio controls src=\"/_emdash/api/media/file/01M59MGY9QE5VB6FW2ZWQZGGT7.mp3\"></audio></figure>"},{"_type":"block","_key":"key-7-jrznj","style":"normal","children":[{"_type":"span","_key":"key-4-s80c6","text":"喜愛研究台菜與台灣小吃的人，都會去深掘台南，我年輕時就因此經常去台南吃吃喝喝，驚訝的是，檳城跟台南，相似處甚至遠多於相異處，對於思考台菜、研究台菜的人，去認識檳城飲食風貌與演變會是很好的拓展點，我未來幾年肯定會常常去檳城 "},{"_type":"span","_key":"key-5-1b86p","text":"做飲食研究","marks":["strike-through"]},{"_type":"span","_key":"key-6-zhbv7","text":" 暴飲暴食"}]},{"_type":"block","_key":"key-9-ise9y","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-8-5oxgh","text":"檳城會說福建話的人多，甚至非福建人如潮州、客家、粵，也都習慣了福建話，台南也是，很多客家人甚至都忘了怎麼講客家話，而是以福建話為母語了"}]},{"_type":"block","_key":"key-11-ki9uh","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-10-q3te7","text":"都曾是殖民時代的重要港口，市中心高樓少，古房小巷保存很多，當然檳城因為列入世界文化遺產，保留與維護的更完善，尤其是所謂 shophouse、排屋、殖民時代的洋房…等等。"}]},{"_type":"block","_key":"key-13-gb3ko","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-12-foyx8","text":"飲食的調味都很細緻，即使平民飲食也講究，高檔人家的飲食則有低調的炫富感 (檳城有娘惹菜，台南則是辦桌菜、酒家菜、阿舍菜)，窮有窮的講究富有富的寬裕"}]},{"_type":"block","_key":"key-16-35f34","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-14-2rsg1","text":"馬來海南人發明的 roti babi跟台南的棺材板不同源頭卻極為相似，都是西方餐點的華人式改良，吃的時候都是類似西餐使用刀叉，roti 是印度語的一種烤餅、馬來語借來指稱麵包，babi是豬肉。\n\n"},{"_type":"span","_key":"key-15-8cgxy","text":"食物味道姑且不論，我覺得值得玩味，海南人作為華人的一族裔，卻使用馬來語 roti babi 來命名這道料理，問題是馬來人不吃豬肉，這是一個伊斯蘭教徒看到會搖頭的料理，為何要借用馬來語呢？想到台南的棺材板，也是乍聽會讓人有些生畏的名字，除了因為外型，有沒有可能最早的料理發明人對於這種中西合併式餐點能否賣得出去，心裡也是存疑，畢竟所謂創意料理常常跟暗黑料理只有一線之隔呀🤣，最後抱著豁出去的想法，先用料理名稱博取注意吧，即便過客不敢吃，也容易再把這個料理名稱用口語傳播出名氣，以上純粹是個人旅途中的胡思亂想。"}]},{"_type":"image","_key":"key-17-38olw","asset":{"_type":"reference","_ref":"01M59MGY7S5W8T9KNE9JYHV34B","url":"/_emdash/api/media/file/01M59MGY7S5W8T9KNE9JYHV34B.jpg"},"alt":"","caption":"roti babi 或海南雞排、豬排，習慣搭配 李派林(Lea and Perrins)的伍斯特醬，你覺得看起來像不像台南棺材板呢","alignment":"center"},{"_type":"block","_key":"key-19-uqzjy","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-18-7hkax","text":"天氣差不多，日照也充足，可能這是都很愛喝飲料口味偏甜的原因之一，檳城用椰糖、棕櫚糖，台南則是用冬瓜糖、紅糖，都各有獨特香氣"}]},{"_type":"block","_key":"key-21-idv2o","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-20-5qp8p","text":"檳城的福建面跟台南的擔仔麵是兄弟! 都是原鄉福建蝦麵的變化! 甚至，檳城還有知名的\"擔仔飯\"，這是我自己稱呼的，實際的名稱是Nasi Kandar，也是檳城必吃的美食之一"}]},{"_type":"image","_key":"key-22-gapud","asset":{"_type":"reference","_ref":"01M59MGY824HDA0MFQ2217849K","url":"/_emdash/api/media/file/01M59MGY824HDA0MFQ2217849K.jpg"},"alt":"","caption":"店家彩繪舊時代擔仔飯Nasi Kandar樣貌當做行銷","alignment":"center"},{"_type":"block","_key":"key-25-5whbi","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-23-svr3h","text":"檳城/台南的福建話都保留得比其他地方完整道地（跟其他語言的借用詞較少），生活步調較慢講話較慢 (台南人講話慢走路慢是出名的)，語言是文化的傳播工具，語言越是穩定，既有文化的傳承更是穩定，這趟從北馬到中部，越往南，福建話越像馬來話，語速快且腔調重，跟馬來語的借用語非常多，與其說是像馬來語的福建話，在我耳中聽起來是更像福建話的馬來語。\n\n"},{"_type":"span","_key":"key-24-pe2wg","text":"當然福建話本身在原鄉福建，就因地域不同有非常多分支，即便在台灣，台語也有山線腔、海線腔、宜蘭腔…等的明顯差別，大馬福建話因南北距離差別大也是可想而知。我在檳城大概一句福建話能聽懂 7 成，到了巴生，只能聽懂 3成，瞬間感覺自己台語能力變好爛（但其實不是），移民的語言來自原鄉，卻並不歸屬原鄉，而是屬於遷移後的他鄉，以及屬於已落地生根的社群家鄉所有，大馬的福建話雖名為福建，曾被稱為閩南語的台灣台語，語言內涵的文化都已經是與原鄉福建八竿子打不著的事物了。\n"}]},{"_type":"block","_key":"key-27-mv03k","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-26-l7ils","text":"很多很多傳統廟宇跟佛道教慶典儀式像是盂蘭節（中元節），愛拜拜敬神酬神，台南也是，信仰是維繫當地華人社群傳統的重要媒介。在大馬，有蠻多台灣未見的神明，最常在路邊看到的小廟，起先以為是土地公，聽當地人說才知道是拿督公，這次去檳城適逢中元，見到很特殊的大士爺祭典，上網一查，台灣僅有嘉義民雄有信仰大士爺，歷史非常久，嘉義這間廟跟檳城是否有歷史聯繫頗讓人好奇。"}]},{"_type":"image","_key":"key-28-vbpzj","asset":{"_type":"reference","_ref":"01M59MGY7CP2WTAMA4A30WABQX","url":"/_emdash/api/media/file/01M59MGY7CP2WTAMA4A30WABQX.jpg"},"alt":"","caption":"建德堂(大伯公廟)內有一座金碧輝煌的酬神戲台","alignment":"center"},{"_type":"block","_key":"key-33-tupro","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-29-7bc3p","text":"異常多古老的糕點店，從傳統中式港式的糕點到現代一點的西式都有，也因為宗教祭典頻繁，部分老店會在祭典製作給神明的特殊供品糕點，例如下圖左上的 胡榮發餅舖 ( "},{"_type":"span","_key":"key-31-jx9it","text":"影片","marks":["key-30-wfkcu"]},{"_type":"span","_key":"key-32-ktb5q","text":" ) 就有很多連我都沒看過的罕見閩南老式糕點。台南的九層糕跟檳城的娘惹糕出自同源，但往不同方向下功夫。"}],"markDefs":[{"_type":"link","_key":"key-30-wfkcu","href":"https://youtu.be/1IQpv3j2v5c?si=Z4mziJxn_nbdwYH9","blank":true}]},{"_type":"image","_key":"key-34-xqqpi","asset":{"_type":"reference","_ref":"01M59MGY9CWNZWCHC22861HY8Y","url":"/_emdash/api/media/file/01M59MGY9CWNZWCHC22861HY8Y.jpg"},"alt":"","caption":"我實在很喜愛外皮酥脆、內餡清爽的咖央角，上右圖中有夾必糕（kuih kapit ），可惜我當下有眼無珠沒認出來","alignment":"center"},{"_type":"block","_key":"key-37-f38dd","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-35-i66s8","text":"檳城/台南都醬油成癮，檳城人喜愛的黑醬油（kicap manis 一種濃甜味的老抽醬油）、蝦醬，台南人則喜歡醬油膏、白醬油，甚至都會拿醬油來當水果的調味醬。檳城的羅惹Rojak（馬來語意思是大雜燴），就是用黃瓜、鳳梨等水果，加上炸油條、蝦餅、魚餅以及花生碎，然後淋上蝦膏混合黑醬油的醬汁去食用的一種沙拉，讓我吃起來很困惑，台南也有非常類似的鹹甜混合的飲食習慣（同樣讓我困惑）！台南當地水果行都會賣水果附上白糖紅糖、甘草粉、薑泥、醬油膏、薑之類的沾醬!! 檳城朋友來台南吃到，應該會有親切感。\n\n"},{"_type":"span","_key":"key-36-36pz0","text":"這種飲食習慣，應該是同源的飲食習慣，台灣在荷治時代，引進了非常多東南亞與美洲的水果品種，不過在那個時代，植物育種來提升品質的技術還不普遍，水果的甜度並不如現代，通常會帶著酸味與蔬果的生澀味，因而加入鹽糖等調味料，來提升水果的風味，是古早閩粵移民面對異國水果的共同料理本能，不過 Rojak 這個詞彙在殖民時代前的印尼爪哇語中就有類似的食物，由此可見這個食物最早可能是原生南亞，隨著中國商人與華人移民到來後，帶來新的醬油調味料去調整口味，爾後才逐漸變成我們如今在新馬等地看到的模樣。"}]},{"_type":"image","_key":"key-38-uzhsh","asset":{"_type":"reference","_ref":"01M59MGY6Y43054TYTTA1A70FW","url":"/_emdash/api/media/file/01M59MGY6Y43054TYTTA1A70FW.jpg"},"alt":"","alignment":"center"},{"_type":"image","_key":"key-39-1rn80","asset":{"_type":"reference","_ref":"01M59MGY7J0T1C1M5TVCSCT2H8","url":"/_emdash/api/media/file/01M59MGY7J0T1C1M5TVCSCT2H8.jpg"},"alt":"","caption":"滷肉（lor bok）是不是很像香腸熟肉","alignment":"center"},{"_type":"block","_key":"key-43-qfr9b","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-40-cuo4a","text":"檳城的滷肉（lor bok） 就是一種以台灣的五香豬肉捲或叫雞捲 (沒雞肉) 為主的炸料拼盤，是的，不是只有現代人懂用炸物解憂，古人也知道，沒有什麼問題是炸物不能解決的對吧（大笑），吃lor bok的時候，還會配其他炸豆腐、炸粿等等的炸料，沾甜辣醬吃，跟台南的香腸熟肉，在料理手法跟醬料都非常相似。不過台灣豬肉品質實在太高，台灣料理對加五香粉的依賴就低很多，調味下的份量相對輕，我們更追求料理要能凸顯或不能遮掩食材的原味，以及油炸的技巧，這應該是受日本文化影響，而馬來炸料內餡，用更多功夫在精進辛香料去輔味，我在陳靜宜老師的書看到檳城博愛堂的五香粉是一絕，當地朋友送了我幾包回台，的確是我至今聞過香氣最強烈的五香粉！\n\n"},{"_type":"span","_key":"key-41-obhfc","text":"既然說到檳城 lor bok，咱們台南知名的美玉炸料也很有特色，但讓我大開眼界的是怡保的忠記大樹頭炸料粉，攤子包含了至少六種族裔以上的食材，像是廣東人的炸雲吞、百花油條、客家人的釀豆腐、福州人的魚丸炸以及馬來在地的炸沙葛！是的，只要是好吃的，小孩才做選擇，大馬人全都要吃😂觀察大馬餐飲裡多元文化的碰撞是除了吃以外的莫大樂趣。此外下圖的炸料粉可注意看其中的(豆)芽菜，怡保的芽菜跟台灣的長相不同，短肥但多汁可口，據說是水質不同，所以大馬其他城市也吃不到這種芽菜。\n\n"},{"_type":"span","_key":"key-42-b0u4i","text":"另外如果你在大馬菜單看到油炸鬼這個詞，指的是油條，油炸鬼是油炸粿的諧音，是的，馬來華人也莫名其妙很迷諧音。"}]},{"_type":"image","_key":"key-44-mq1lk","asset":{"_type":"reference","_ref":"01M59MGY9FXWM9WFDDATH6V84H","url":"/_emdash/api/media/file/01M59MGY9FXWM9WFDDATH6V84H.jpg"},"alt":"","caption":"乾的炸料粉本體就是廣東梅州客家人的醃粉麵，但還可以點湯的 laksa 或其他族群的麵食來搭配炸料","alignment":"center"},{"_type":"block","_key":"key-46-o4tfy","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-45-b6ye4","text":"檳城人都異常喜歡豬油、豬油渣與講求炒菜的生猛鑊氣，薄餅有豬油渣，粿條湯、福建麵也都有，檳城人對炒粿條的要求就如同台南人對待炒鱔魚意麵，沒鑊氣，料理就沒了靈魂，這點我感同身受，幾年前為了吃稻糠跟灶去炒的鱔魚，特地跑了一趟台南新營，本身過往是不喜愛炒鱔魚，但沒想到用稻糠當柴火去炒的鱔魚，清脆並帶著些微煙燻味，好吃到我當場說不出話，完全顛覆從小所吃過的鱔魚、泥鰍、土虱這類土味魚的記憶，都說香火能增添神明的神力，這食物沾染的鑊氣就是濃縮的人間煙火，為你我凡夫俗子們增添為生活拼搏的動力。如果你至今尚未體驗過鑊氣撲面的料理，記得去檳城務必嚐嚐柴燒的炒粿條或是吉隆坡用黑醬油炒的福建麵。（台南新營的清香鱔魚麵好像已經歇業，甚憾）"}]},{"_type":"image","_key":"key-47-ove6g","asset":{"_type":"reference","_ref":"01M59MGY868FKZ2CMYZN3XS9X6","url":"/_emdash/api/media/file/01M59MGY868FKZ2CMYZN3XS9X6.jpg"},"alt":"","alignment":"center"},{"_type":"block","_key":"key-59-9wb6o","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-48-nnq0j","text":"檳城的薄餅（Popiah）在台灣叫春捲，台南人更常叫潤餅，原因可能是殖民時代與荷蘭人的接觸頻繁，其用語Loempia音同潤餅的台語，台南人吃潤餅的習俗比台灣其他縣市更悠久，發展出的與中國原鄉的更精細，而且內餡獨特，台南還會放一種皇帝豆（長相類似大馬的臭豆，但不臭），推薦讀者可試試台式春捲天花板的台南阿真潤餅。\n\n"},{"_type":"span","_key":"key-49-0whct","text":"馬來西亞的薄餅內餡放的是沙葛，一種類似馬鈴薯口感的根莖類，無論台式或馬來西亞的春捲，我都不喜愛，個人愛的是越南春捲，但這趟特別為了嘗試娘惹人的變型薄餅「金杯（Kueh Pie Tee 發音為粿派提）」，Kueh 就是米粿類食品，pie 則是類似派皮的意思，做法是用模具沾春捲皮的米漿後，去油炸定型，然後放入跟傳統薄餅相同的餡料，吃的時候就能優雅的一口吃，類似英式下午茶的一口甜點。\n\n"},{"_type":"span","_key":"key-50-p9jxk","text":"不過正好寫文當下，看到新加坡的一個美食研究者的影片，在他的考究中（"},{"_type":"span","_key":"key-52-c2zna","text":"影片連結","marks":["key-51-fxb4e"]},{"_type":"span","_key":"key-53-ro7y8","text":" / "},{"_type":"span","_key":"key-55-0qjoc","text":"報導連結","marks":["key-54-mizke"]},{"_type":"span","_key":"key-56-ny2my","text":"），顛覆了過往認為金杯起源自娘惹人料理的說法，提出Pie tee 可能是源自 patty iron module ，這種最早是美國的瑞典移民開始使用的長柄杯狀料理模具，這種料理手法上世紀 50 年代流傳到新加坡，調整後的做法所用的米漿的原料、內餡與醬料，和薄餅太雷同，使得 Kueh Pie Tee 又被稱呼為新加坡薄餅，而被記載到新加坡人的食譜中，時間久了就被誤以為是娘惹人的傳統料理！\n\n"},{"_type":"span","_key":"key-57-w9hq9","text":"我想到所謂月亮蝦餅在台灣，也常被誤會是傳統泰國菜（其實是台菜），以及北美的左宗棠雞其實是台菜而非傳統中國菜，並且跟左宗棠一點關係都沒有，不過精緻典雅的炸金杯會被誤認為是娘惹人傳統料理，可見娘惹料理的細膩品味是多麼深入人心。\n\n"},{"_type":"span","_key":"key-58-or2a1","text":"小巧的炸物更不能遺漏印度人的街頭美食Pani Puri，乍看像是台式地瓜球，吃法跟金杯一樣，是將餡料跟醬汁倒入其中，不過調味汁是完全的印度風味，一口吃下享受各種香料的爆漿快感，馬來西亞各城市的小印度區都有很多人賣。"}],"markDefs":[{"_type":"link","_key":"key-51-fxb4e","href":"https://youtu.be/yFO2cLUDagE?si=Iq6d2CaIok5NTNHe","blank":true},{"_type":"link","_key":"key-54-mizke","href":"https://explore.airasia.com/assets/blt6744ea2e5ed5ef73/pie-tee-the-nyonya-treat-with-surprisingly-foreign-origins","blank":true}]},{"_type":"image","_key":"key-60-qukyf","asset":{"_type":"reference","_ref":"01M59MGY983QXMTC9JRZEH9B3B","url":"/_emdash/api/media/file/01M59MGY983QXMTC9JRZEH9B3B.jpg"},"alt":"","caption":"Popiah 與 Kueh Pie Tee","alignment":"center"},{"_type":"block","_key":"key-62-s0r1e","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-61-rc351","text":"檳城與台南都混合許多福州、潮汕的飲食，像是米粉、魯麵、粥、粿條、魚丸，因此都有各式各樣的粿、水粿、粿角、紅龜粿…. 台南最出名碗粿，還登上總統國宴菜\n"}]},{"_type":"block","_key":"key-64-4obun","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-63-u5xmj","text":"都有使用粉粿粉條的古老剉冰，例如檳城的煎蕊（cendol），調味使用椰奶、棕櫚糖，配料則是紅豆與斑斕葉製作出的粉條，是因在地材料而做出的調整，台南有很多剉冰老店，像是我很喜歡福興號蘇家冰店，台南的冰品特色是配料種類異常豐富，粉粿、粉條、粉圓、湯圓、芋圓、麵茶、仙草到各式豆類甚至現代點的布丁、水果，非把客人逼出選擇困難症不可的架勢，其實，若把檳城的煎蕊（cendol）拿來台南賣，肯定也會受歡迎，同樣，若是把台式剉冰那去檳城賣，也肯定受喜愛\n"}]},{"_type":"block","_key":"key-76-lwdw1","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-65-ctcxy","text":"荷蘭人的情書：荷蘭人在台南跟檳城都留下許多飲食痕跡，也都有紅毛這個指涉洋人的詞彙，像是檳城的紅毛路、紅毛樓，當然，航海時代的葡萄牙人也有，這一趟我有沒去麻六甲與麻坡，但據說當地是有不少土生葡萄牙人，之後會再安排時間去品嚐知名的葡式烤魚等料理。\n\n"},{"_type":"span","_key":"key-66-wxdvc","text":"夾必糕（kuih kapit ）是一種用鐵盤夾起來烤的椰漿味扁平蛋捲(下方有網路影片)，我在檳城看到好幾次，以為只是普通餅乾就沒品嚐（"},{"_type":"span","_key":"key-67-hgdxh","text":"所以在馬來西亞，真的不要有太多先入為主的想法，才不會錯過體驗新事物的機會","marks":["strong"]},{"_type":"span","_key":"key-68-dhop0","text":"），kuih kapit 在新加坡則被稱為Kueh Belanda （馬來語意為「荷蘭蛋糕」），俗稱「情書」，是外型為圓筒狀的蛋捲，在印尼也有一樣的食物，不過蠻有趣的點是雖然被稱為荷蘭蛋糕，但新年吃蛋捲這個習慣卻是來自西班牙人。\n\n"},{"_type":"span","_key":"key-69-m2908","text":"我發現西語在馬來語詞彙中的影響頗低，英國、荷蘭、葡萄牙的比例卻是較高的，而這三個國家在歷史上都有殖民過馬來西亞，因此這種蛋捲被稱為荷蘭蛋糕，未必是荷蘭人引進，可能是荷蘭治理麻六甲的時期，有商人由西班牙人統治的馬尼拉引進，一如台南將碗豆稱為荷蘭豆，更多的是指稱治理者，未必真的就是原產地。若對上述殖民時代的語言流變感興趣，推薦中研院研究員"},{"_type":"span","_key":"key-71-7lmc0","text":"鄭維中的這篇訪問報導","marks":["key-70-2x4p2"]},{"_type":"span","_key":"key-72-5kz0v","text":"。\n\n"},{"_type":"span","_key":"key-73-6b48j","text":"日本也同樣佔領過馬來西亞，只是在太平洋戰爭期間，掠奪財富重於建設發展，因此遺留的多數是歷史傷痕，沒有在大馬文化中留下顯著的融合遺產，台灣繼承很多日式飲食文化，但在大航海殖民時代沒有接收到西班牙蛋捲這個飲食傳承（或者曾有，卻失傳在歷史中），往好的看，台灣五花八門的現代蛋捲或蛋黃酥，卻是新馬等地所未見的商業熱潮，就像一個沒有父母遺產卻打拼出宏偉事業的勵志故事，"},{"_type":"span","_key":"key-74-hjffh","text":"餐飲有所傳承未必保證能發揚光大，沒有傳承的創新餐飲也未必無法成功","marks":["strong"]},{"_type":"span","_key":"key-75-km79s","text":"（下一篇會談到飲食傳承），像是台南有間百年歷史的連德堂日式雞蛋煎餅，傳承自日治時代，別具風味，中間卻也曾經營慘淡，歇業數十年後才幸運地重新開業。\n"}],"markDefs":[{"_type":"link","_key":"key-70-2x4p2","href":"https://smiletaiwan.cw.com.tw/article/2986"}]},{"_type":"htmlBlock","_key":"key-77-w4q7x","html":"<blockquote class=\"tiktok-embed\" cite=\"https://www.tiktok.com/@makanmana/video/7186152179328175387\" data-video-id=\"7186152179328175387\" style=\"max-width: 605px;min-width: 325px;\" > <section> <a target=\"_blank\" title=\"@makanmana\" href=\"https://www.tiktok.com/@makanmana?refer=embed\" rel=\"noopener\">@makanmana</a> Eng Seng Kuih Kapit <a title=\"engseng\" target=\"_blank\" href=\"https://www.tiktok.com/tag/engseng?refer=embed\" rel=\"noopener\">#engseng</a> <a title=\"kuihkapit\" target=\"_blank\" href=\"https://www.tiktok.com/tag/kuihkapit?refer=embed\" rel=\"noopener\">#kuihkapit</a> <a title=\"baked\" target=\"_blank\" href=\"https://www.tiktok.com/tag/baked?refer=embed\" rel=\"noopener\">#baked</a> <a title=\"charcoalbaked\" target=\"_blank\" href=\"https://www.tiktok.com/tag/charcoalbaked?refer=embed\" rel=\"noopener\">#charcoalbaked</a> <a title=\"dessert\" target=\"_blank\" href=\"https://www.tiktok.com/tag/dessert?refer=embed\" rel=\"noopener\">#dessert</a> <a title=\"cookies\" target=\"_blank\" href=\"https://www.tiktok.com/tag/cookies?refer=embed\" rel=\"noopener\">#cookies</a> <a title=\"malaysianfood\" target=\"_blank\" href=\"https://www.tiktok.com/tag/malaysianfood?refer=embed\" rel=\"noopener\">#malaysianfood</a> <a title=\"chinesefood\" target=\"_blank\" href=\"https://www.tiktok.com/tag/chinesefood?refer=embed\" rel=\"noopener\">#chinesefood</a> <a title=\"peranakanfood\" target=\"_blank\" href=\"https://www.tiktok.com/tag/peranakanfood?refer=embed\" rel=\"noopener\">#peranakanfood</a> <a title=\"kulinermedan\" target=\"_blank\" href=\"https://www.tiktok.com/tag/kulinermedan?refer=embed\" rel=\"noopener\">#kulinermedan</a> <a title=\"kulinerpenang\" target=\"_blank\" href=\"https://www.tiktok.com/tag/kulinerpenang?refer=embed\" rel=\"noopener\">#kulinerpenang</a> <a title=\"kulinertiktok\" target=\"_blank\" href=\"https://www.tiktok.com/tag/kulinertiktok?refer=embed\" rel=\"noopener\">#kulinertiktok</a> <a title=\"kulinerindonesia\" target=\"_blank\" href=\"https://www.tiktok.com/tag/kulinerindonesia?refer=embed\" rel=\"noopener\">#kulinerindonesia</a> <a title=\"kulinerjakarta\" target=\"_blank\" href=\"https://www.tiktok.com/tag/kulinerjakarta?refer=embed\" rel=\"noopener\">#kulinerjakarta</a> <a title=\"kulinerbandung\" target=\"_blank\" href=\"https://www.tiktok.com/tag/kulinerbandung?refer=embed\" rel=\"noopener\">#kulinerbandung</a> <a title=\"kulinersurabaya\" target=\"_blank\" href=\"https://www.tiktok.com/tag/kulinersurabaya?refer=embed\" rel=\"noopener\">#kulinersurabaya</a> <a title=\"penangfood\" target=\"_blank\" href=\"https://www.tiktok.com/tag/penangfood?refer=embed\" rel=\"noopener\">#penangfood</a> <a title=\"penangfoodie\" target=\"_blank\" href=\"https://www.tiktok.com/tag/penangfoodie?refer=embed\" rel=\"noopener\">#penangfoodie</a> <a title=\"jajanantiktok\" target=\"_blank\" href=\"https://www.tiktok.com/tag/jajanantiktok?refer=embed\" rel=\"noopener\">#jajanantiktok</a> <a title=\"jajananmedan\" target=\"_blank\" href=\"https://www.tiktok.com/tag/jajananmedan?refer=embed\" rel=\"noopener\">#jajananmedan</a> <a title=\"streetfood\" target=\"_blank\" href=\"https://www.tiktok.com/tag/streetfood?refer=embed\" rel=\"noopener\">#streetfood</a> <a target=\"_blank\" title=\"♬ original sound - Makanmana - MakanMana\" href=\"https://www.tiktok.com/music/original-sound-Makanmana-7186152202230205210?refer=embed\" rel=\"noopener\">♬ original sound - Makanmana - MakanMana</a> </section> </blockquote> <script async src=\"https://www.tiktok.com/embed.js\"></script>","originalBlockName":"core/html"},{"_type":"block","_key":"key-79-zi7y4","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-78-d66lg","text":"檳城與台南都有老一輩的傳統手工藝職人，木工、金工、鐵匠、裁縫、刺繡、編織甚至殯葬業的紙紮…等等，時代變遷，要原汁原味保留舊手藝是有些不現實，這些非物質文化如果能引導，就會是文創產業的底蘊，當然並不容易，我在檳城看到一些年輕經營者試圖這麼做，但明顯尚在摸索的階段，台南的文創產業是比檳城走的更快、更成熟些。"}]},{"_type":"block","_key":"key-83-rnbjm","style":"normal","children":[{"_type":"span","_key":"key-80-xyxyx","text":"\n"},{"_type":"span","_key":"key-81-h8wkx","text":"檳城與台南，對我來說都是餐飲的博物館，很多跨越不同年代、不同族群的食物風味，除此也不斷在創新，我認為兩地若可以多些未來交流，會產生更多可能性。\n"},{"_type":"span","_key":"key-82-27ejz","text":"現代餐飲的一面，礙於時間與心力有限，以後再分享。接下來的兩篇我繼續深談馬來飲食的各個面向、過去與未來。"}]},{"_type":"htmlBlock","_key":"key-84-4amb5","html":"[wpb_post_list_table]","originalBlockName":"core/shortcode"}]', '檳城人都異常喜歡豬油、豬油渣與講求炒菜的生猛鑊氣，薄餅有豬油渣，粿條湯、福建麵也都有，檳城人對炒粿條的要求就如同台南人對待炒鱔魚意麵，沒鑊氣，料理就沒了靈魂，這點我感同身受', 136, 'https://flavorinsight.com/wp-content/uploads/2025/04/南島相遇：檳城與台南的飲食交流.mp3
8228830
audio/mpeg
');
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K58NCCYR9YF3WSH6DXDMK', 'klang-bak-kut-teh-origins', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-14T11:22:07.000Z', '2026-10-20T04:08:37.239Z', '2024-10-14T11:22:07.000Z', NULL, NULL, 3, '01M5BQYAS3CVJADNV62K79NEC3', NULL, 'zh-TW', '01M59K58NCCYR9YF3WSH6DXDMK', '馬來筆記 Part4 再談馬來西亞飲食（上）', '{"id":"01M59MGY93HVGMTCKJGNBXJDRA","provider":"local","filename":"IMG_20240904_120800-scaled.jpg","mimeType":"image/jpeg","width":2560,"height":1920,"alt":"馬來筆記 Part4 再談馬來西亞飲食（上）","meta":{"storageKey":"01M59MGY93HVGMTCKJGNBXJDRA.jpg","caption":null,"blurhash":null,"dominantColor":null}}', '[{"_type":"block","_key":"key-2-qzimo","style":"h3","children":[{"_type":"span","_key":"key-1-6o9l4","text":"• 只要好吃就不奇怪"}]},{"_type":"block","_key":"key-4-d4fdf","style":"normal","children":[{"_type":"span","_key":"key-3-w9us7","text":"文章篇幅很長，下面是AI生成的摘要聲音檔，可聽聽，有興趣再讀全文"}]},{"_type":"embed","_key":"key-5-xls67","url":"/_emdash/api/media/file/01M59MGY9BRWS5BKA1J43QJYMH.mp3","provider":"audio","html":"<figure class=\"wp-block-audio\"><audio controls src=\"/_emdash/api/media/file/01M59MGY9BRWS5BKA1J43QJYMH.mp3\"></audio></figure>"},{"_type":"block","_key":"key-7-ppnvf","style":"normal","children":[{"_type":"span","_key":"key-6-xubwk","text":"混合是移民文化的特徵，檳城的福建麵就是如此，同樣是福建裔，蝦湯頭出現在靠海的福建縣，靠山的福建縣則較多滷麵，面對來自各處的福建移民，檳城小販想讓生意做大，都賣是種選擇，混著賣更是一種可嘗試的可能性，若沒特別要求，檳城的福建麵上桌就是（米）粉混合（黃）麵，甚至你還可點一碗麵蝦湯滷湯各半的 mixed 湯頭，就好像鴛鴦火鍋。吉隆坡一家友愛海鮮麵（Yu Ai），麵有咖哩湯頭也有東央湯頭，老闆還賣兩者混在一起的怪味湯頭，怪隨怪，但著實美味極了。檳城有一家三味雲吞麵，顧名思義就是一盤雲吞撈麵有三種口味，店家甚至還有七種口味的浮誇版本！"}]},{"_type":"block","_key":"key-9-dbz7k","style":"normal","children":[{"_type":"span","_key":"key-8-7mbwo","text":"米粉混合麵條，台灣很多小吃攤也有這種做法，什麼都摻一些、混看看，例如個人覺得台灣有個非常神奇的混合食物：蛋花貢丸味噌湯，三種都可獨立的湯品，卻被奇妙的統一，以簡單的味噌湯作為基準，蛋貢味噌湯是有點過於豐盛張揚，可是搭配簡樸的涼麵，一豐一簡似乎讓饕客的味蕾達成平衡。想起近年來在辱義之路越走越遠的必勝客披薩🤣"}]},{"_type":"block","_key":"key-12-8nxwc","style":"normal","children":[{"_type":"span","_key":"key-10-q821g","text":"許多看似不理性不科學的食物混搭，在移民社會是很務實的折衷做法","marks":["strong"]},{"_type":"span","_key":"key-11-g7hqx","text":"，也許是為了應消費者提出的需要，也可能是店家為增加銷售的行銷手法，又或是一個將異鄉食材由（陌）生到熟（悉）的必然摸索過程，非移民社會也會有，只是移民社會的飲食混搭更頻繁、更見怪不怪，比起追求料理正宗與否，更著重因人時地。"}]},{"_type":"block","_key":"key-14-xlgcl","style":"h3","children":[{"_type":"span","_key":"key-13-4ftuf","text":"• 傳統需要守護但不能僵固"}]},{"_type":"block","_key":"key-16-gsfw4","style":"normal","children":[{"_type":"span","_key":"key-15-t85jh","text":"移民為了營生求變通，不僅是要面對陌生族裔客群，還有陌生食材與調料，多數食物必然容易與原鄉中國有所差異，然而，有心態是四海為家的移民，也有極重傳統認同的移民，在馬來西亞，講究正宗的也大有人在！"}]},{"_type":"block","_key":"key-18-89fld","style":"normal","children":[{"_type":"span","_key":"key-17-864v8","text":"以我本身來說，隨著中國對台人不友善的政策越來越多，如今根本無法去香港，對 1450 的我是一個高危險的雷區，時常遺憾再也吃不到許多懷念的香港美食，不過去年幾個熟識的香港饕客朋友紛紛跟我說在馬來西亞吃到正宗老港味的食物，這趟我是帶著幾分考校檢驗這種說法的心態去大馬。"}]},{"_type":"block","_key":"key-20-n3tvq","style":"normal","children":[{"_type":"span","_key":"key-19-v55le","text":"結果是好的，檳城、怡保與吉隆坡都遇到極滿意的港式食物，我完全不懷念香港了！以後嘴饞，去馬來西亞就可滿足對老港味食物的念想，無論是雲吞麵、叉燒撈麵、燒肉、煲仔飯、牛腩粉、老火煲湯、生蝦煨伊麵、生滾粥、點心、糕餅…等等，都有極出色保有老港味的老店。在吉隆坡也偶然吃了一家店名直白普通的港飲港食餐廳，可味道就像是香港那些半世紀老店，餐點品項也很傳統。"}]},{"_type":"image","_key":"key-21-yrdm9","asset":{"_type":"reference","_ref":"01M59MGY9A4F8PWMF31X70DS51","url":"/_emdash/api/media/file/01M59MGY9A4F8PWMF31X70DS51.jpg"},"alt":"","alignment":"center"},{"_type":"block","_key":"key-23-jla0u","style":"normal","children":[{"_type":"span","_key":"key-22-6owu3","text":"前些時候一個香港人司機則跟我分享另一個老港味飲食所在，他這麼說：「現在香港食物又貴又走味，要吃最正宗的要去溫哥華，很多香港老師傅都移居國外了」，如果有熟悉溫哥華的朋友，可以告訴我是否如他所言。"}]},{"_type":"block","_key":"key-31-0ttsh","style":"normal","children":[{"_type":"span","_key":"key-24-rb67x","text":"我看過一種說法，馬來西亞的中菜可以分成三種類型，第一種是大量使用當地香料的"},{"_type":"span","_key":"key-25-40w62","text":"娘惹式中菜","marks":["strong"]},{"_type":"span","_key":"key-26-cgy5h","text":"，裡面已經融合了印度菜、馬來菜、印尼菜甚至西方料理的各種手法，歷史古老，卻頗有當代 fusion 料理的精神，新意十足，娘惹料理由於有大量辛料香草需要預先且精細處理，一邊吃不禁一邊感嘆其料理都蠻費工，有些甚至可稱上手路菜的程度，也頻頻讓我聯想到古時台南富豪們才能享用的起的阿舍菜；第二種則是大馬"},{"_type":"span","_key":"key-27-kfq9u","text":"不同的華人族裔所共享或共創的料理","marks":["strong"]},{"_type":"span","_key":"key-28-xye83","text":"，例如原生在客家的豬腳醋、芋頭扣肉、釀豆腐，變成即便不是客家裔的其他馬來華人也都會料理來吃，當然細微處可能就有些變化，沒原生的客家菜正統，肉骨茶、海南雞也是這類；第三類才是各族裔"},{"_type":"span","_key":"key-29-72uvw","text":"華人所堅守傳統的中式料理","marks":["strong"]},{"_type":"span","_key":"key-30-ndhk7","text":"。最後，我補充，這六、七年來，中國一些連鎖餐飲品牌，以及潤到東南亞創業的中國人，數量都在急劇增加，他們在馬來西亞所開的中式料理或許可稱為第四類。這四類以第二類最常見，希望這分法能給你一個馬來中菜的大致輪廓。"}]},{"_type":"image","_key":"key-32-ayjgn","asset":{"_type":"reference","_ref":"01M59MGY99321FVPNRCZCADQJC","url":"/_emdash/api/media/file/01M59MGY99321FVPNRCZCADQJC.jpg"},"alt":"","caption":"娘惹式中菜","alignment":"center"},{"_type":"block","_key":"key-35-hrpzl","style":"normal","children":[{"_type":"span","_key":"key-33-q13aw","text":"\n"},{"_type":"span","_key":"key-34-6a7cc","text":"除了許多粵人老店，堅守飲食傳統，大馬潮州人、客家人、福建人也都有各自對飲食傳統的重視，例如潮州粥或客家麵（又稱大埔麵），基本上整個東南亞，都有潮州人開的粥餐廳，雖然個人對粥品絲毫不愛（愛吃硬飯的客家 DNA 作祟呀）。"}]},{"_type":"block","_key":"key-37-8c8k2","style":"normal","children":[{"_type":"span","_key":"key-36-s4wsr","text":"這趟在巴生（Klang），特別去潮興飯粥吃到傳統潮州粥，可惜撲空，好在在潮鄉故事館吃到創新的炒粥。潮鄉餐廳的炒粥，味道乍聞像台北的肉粥，可是湯水又被炒的更少更乾，蝦米魷魚等乾料的鮮味，加上豬油渣、炸油蔥酥、芋頭粒的香味，瀰漫在濃綢的粥米中，直衝腦門，是非常特殊的料理，，有機會去巴生除了肉骨茶，也務必試試看。"}]},{"_type":"image","_key":"key-38-2ys0k","asset":{"_type":"reference","_ref":"01M59MGY9154475CN6FKJT8EAT","url":"/_emdash/api/media/file/01M59MGY9154475CN6FKJT8EAT.jpg"},"alt":"","caption":"香氣炸裂的炒粥","alignment":"center"},{"_type":"block","_key":"key-43-pknsx","style":"normal","children":[{"_type":"span","_key":"key-39-sog0d","text":"但講到粥，個人較喜歡檳城的李平記清粥("},{"_type":"span","_key":"key-41-9jvvm","text":"相關報導","marks":["key-40-1l4ol"]},{"_type":"span","_key":"key-42-meiyh","text":")，據稱口味源自創辦人祖籍的福建泉州（想到五月天阿信😌），李平記的配菜調味都清淡，蕃薯白粥與配菜菜色都跟台灣清粥小菜相似，而且是對中低階層也誇張友善的銅板價（台北清粥小菜吃起來價格可以蠻驚人），這類食物絕大多數不是會讓你驚艷的美味，吃的是業主的兢兢業業和濃厚綿長的人情味。題外話，台北清粥小菜我首推中原街的小品雅廚。\n"}],"markDefs":[{"_type":"link","_key":"key-40-1l4ol","href":"https://www.kwongwah.com.my/20240321/%e6%9d%8e%e5%b9%b3%e8%ae%b0%e6%b8%85%e7%b2%a5-%e6%9c%80%e6%9a%96%e5%bf%83%e6%b8%a9%e9%a5%b1/#google_vignette","blank":true}]},{"_type":"block","_key":"key-45-jud45","style":"h3","children":[{"_type":"span","_key":"key-44-culax","text":"• 巴生肉骨茶職人"}]},{"_type":"block","_key":"key-50-1x17g","style":"normal","children":[{"_type":"span","_key":"key-46-jczsh","text":"這次旅程還有幸吃到肉骨茶發明人李文地的長子開的德地肉骨茶（相關歷史可見"},{"_type":"span","_key":"key-48-z17b4","text":"陳靜宜老師的書","marks":["key-47-464fe"]},{"_type":"span","_key":"key-49-zhmfa","text":"），觀光客較少，網上吃過的評價也不高，但老實說，我這趟吃了許許多多食物，唯獨德地肉骨茶是我回台後仍不斷不斷地回憶那段用餐體驗。"}],"markDefs":[{"_type":"link","_key":"key-47-464fe","href":"https://www.books.com.tw/products/0010785203?sloc=main","blank":true}]},{"_type":"image","_key":"key-51-ybw6w","asset":{"_type":"reference","_ref":"01M59MGY904C7R2HVHGE367EVP","url":"/_emdash/api/media/file/01M59MGY904C7R2HVHGE367EVP.jpg"},"alt":"","alignment":"center"},{"_type":"block","_key":"key-53-1og7t","style":"normal","children":[{"_type":"span","_key":"key-52-xl9ol","text":"那是一個彷彿時間暫停又或是穿越時空的空間，店內褪色的桌椅、牆壁上殘破的手寫菜單與缺角的碗盤，端上來的肉骨茶與米飯也顯得有些暗沉，店內客人與老闆皆是褪去黑髮的白髮長者們，客人間歇的細語聲與熱水茶壺的沸騰聲，是德地店內唯二的聲音，有著一般中菜、小吃餐廳罕見的安靜，坦白說，唯獨我是唯一與整家店的氣氛格格不入的遊客，點餐到候餐，我像是考生在等成績，坐立不安，但第一口肉骨茶湯入口，立刻 hold住我的情緒，好厲害呀！"}]},{"_type":"image","_key":"key-54-1uv6x","asset":{"_type":"reference","_ref":"01M59MGY8YK8KEN8VT1JH0HGH8","url":"/_emdash/api/media/file/01M59MGY8YK8KEN8VT1JH0HGH8.jpg"},"alt":"","caption":"牆上很舊的手寫菜單，建議台灣朋友點五花骨或三層肉 會比較接近多數人喜好的豬肉口味","alignment":"center"},{"_type":"block","_key":"key-56-qsb57","style":"normal","children":[{"_type":"span","_key":"key-55-88djx","text":"當代的飲食普遍重視強烈特色與直接的驚奇感，因此廚師會特別強化某一種味道或是對比感，可是德地的肉骨茶，醬味、藥味、肉味三者平衡到不可思議的穩定、無衝突，沒有任何一個味道超過另外兩者一絲一毫，是不分主次的三重奏，這要本身會做料理而且舌頭很敏銳的人，才吃得出他驚人的功夫。"}]},{"_type":"block","_key":"key-58-5k9t7","style":"normal","children":[{"_type":"span","_key":"key-57-yiwu0","text":"難怪德地老闆絕不給辣椒、大蒜等佐料讓客人沾，再多其他味道會破壞平衡，真的為它的網路低評價抱屈！這時代餐飲業者調整配方比政客翻臉還快，德地老闆守著古老平凡的配方，竟用日復一日積累的烹調精準度，讓我見識到把簡樸的配方做到極致的手藝，用電玩遊戲的術語來說，就是把熟練度練到封頂了，如果德地老闆是在日本社會，就會像壽司之神、蛋包飯之神、炸天婦羅之神這樣，被封為肉骨茶之神，但在大馬社會，料理人的地位普遍並不高。"}]},{"_type":"image","_key":"key-59-6lagd","asset":{"_type":"reference","_ref":"01M59MGY8ZAR490THEP9MMQ0EA","url":"/_emdash/api/media/file/01M59MGY8ZAR490THEP9MMQ0EA.jpg"},"alt":"","caption":"慢慢吃肉骨湯 一邊喝著茶 偷聽鄰桌長輩的對話，發現他們也在偷偷打量我","alignment":"center"},{"_type":"block","_key":"key-61-girw9","style":"normal","children":[{"_type":"span","_key":"key-60-x8qx5","text":"若是平常都吃重口味的人，早上要去吃之前，建議不要吃其他食物（上一次被人這麼提醒是要做健康檢查前😂），多喝水讓你的味覺恢復靈敏，吃的時候細嚼慢嚥、小口品嚐，這是一家很考驗客戶味覺敏銳度的店。"}]},{"_type":"block","_key":"key-63-405ay","style":"normal","children":[{"_type":"span","_key":"key-62-q3iqm","text":"檳城的蠔煎也是福建沿海的古老食物，但就沒遇到手藝震撼到我的蠔煎料理人了，畢竟其料理方式極為原始，以現代人口味的標準，台灣發展出來的蚵仔煎絕對更細膩、美味、端的上檯面，作為飲食研究者，檳城的蠔煎就僅是體驗當代食物的古老原型罷了，兩者沒太多可比性。"}]},{"_type":"image","_key":"key-64-2r7e8","asset":{"_type":"reference","_ref":"01M59MGY6R67F1R07C76X1SP38","url":"/_emdash/api/media/file/01M59MGY6R67F1R07C76X1SP38.jpg"},"alt":"","caption":"五月花肉骨茶","alignment":"center"},{"_type":"block","_key":"key-68-p0rni","style":"normal","children":[{"_type":"span","_key":"key-65-t37xh","text":"此外，我還去了肉骨茶發明人李文地的第五子開的五月花，特地品嚐了乾式瓦煲肉骨茶，店內熱熱鬧鬧的氣氛與口味又是截然不同，五月花的配料多，並且有辣椒沾醬，更討現代大眾消費者的口味喜好，好在"},{"_type":"span","_key":"key-66-pjbn8","text":"乾式肉骨茶通常還會給一小碗無調味的原湯讓客人品嚐","marks":["strong"]},{"_type":"span","_key":"key-67-j1ckq","text":"，喝了一口，果然出自同源，創新的背後依舊有守著傳統的底子，但本身覺得乾式瓦煲多吃幾口就覺得無聊，還是湯式的好。"}]},{"_type":"block","_key":"key-70-3pwnz","style":"normal","children":[{"_type":"span","_key":"key-69-xt5kn","text":"許多在地人也推薦毛山稿肉骨茶總行與三美肉骨茶，經常看到台灣超市賣印著毛山稿肉骨茶的湯底包，只是借用名字，並非店家推出的。說真的喜歡吃哪一家肉骨茶很看個人口味，整個巴生市（Klang）約略是台北松山區加上信義區，塞滿了超過 300 家肉骨茶店，即使經過幾個當地人的推薦解說，也是讓我聽到眼花撩亂，如同每個台南人都有自己喜歡的牛肉湯店。"}]},{"_type":"block","_key":"key-72-4ay0m","style":"normal","children":[{"_type":"span","_key":"key-71-fwl7v","text":"我覺得肉骨茶最好的品嚐時間是上午 9 點到 10 點間，剛開店時的湯頭，味道還不夠融合濃郁，而假如 11 點後才去，有些熱門店家肉最好吃的部位可能都賣完了，視店家營業時間，找中間時間去是最穩妥的選擇，若跟我一樣不吃內臟跟腸子，記得交代店家。吃完厚重口味的肉骨茶，正好散步去鄰近的搖搖冰（ Yao Yao Ping Restaurant），點個兩到三種綜合的搖搖冰（就是基隆的泡泡冰）換換口味，務必別忘記嚐嚐他們的炸雞。"}]},{"_type":"image","_key":"key-73-ceric","asset":{"_type":"reference","_ref":"01M59MGY98HSEKZE3P3F21GT68","url":"/_emdash/api/media/file/01M59MGY98HSEKZE3P3F21GT68.jpg"},"alt":"","alignment":"center"},{"_type":"block","_key":"key-75-66y8v","style":"normal","children":[{"_type":"span","_key":"key-74-y0t70","text":"巴生好吃的東西著實不少，在地人還推薦了六嬸面粉糕、巴生菜包、偆園海南咖啡 1956、伸波士頓餐室、平香客家排骨飯店…等特色美食，食量有限就留待下回探索了，若有巴生的朋友，也歡迎推薦我"}]},{"_type":"block","_key":"key-77-diqj5","style":"h3","children":[{"_type":"span","_key":"key-76-55hx0","text":"• 答應我，來馬來西亞別挑食"}]},{"_type":"block","_key":"key-79-47wz9","style":"normal","children":[{"_type":"span","_key":"key-78-m36g0","text":"回到前面提到對市井小民友善的食物，馬來西亞有一種稱為經濟飯 Economy Rice（第一次聽到以為是經濟犯）的飯館，有些地方又稱為雜菜 mixed rice，就是與台式自助餐一樣，許多菜色客人自選、自己打菜，價格平實，兩肉兩菜要價不用 6 馬幣（大約不到台幣 50 元），經濟飯我就只吃過一次，不過路途上有經過時，我都會進去看看有什麼菜色，從菜色可以看出主要客群的族群與區域特色，例如在檳城，閩粵菜明顯比較多，巴生市鄰近馬來西亞最大的巴生港，勞工多，當地潮汕與客家華人都比其他地區活躍，菜色就偏向這菜系，調味厚實，炸物的比例也較高。"}]},{"_type":"image","_key":"key-80-1v5yk","asset":{"_type":"reference","_ref":"01M59MGY94V6XYG8VQ8RBEDT6V","url":"/_emdash/api/media/file/01M59MGY94V6XYG8VQ8RBEDT6V.jpg"},"alt":"","caption":"正開往巴生港方向的長榮貨櫃車  看到莫名感動","alignment":"center"},{"_type":"block","_key":"key-82-qk6cl","style":"normal","children":[{"_type":"span","_key":"key-81-qvuy0","text":"此外也不僅以餐廳方式呈現，我在旅途經過城市外圍或偏僻的街區，看過就在公園或路邊搭個鐵皮屋頂，一張摺疊長桌擺上幾個塑料桶的大鍋菜，就這樣賣經濟飯的也是大有人在，不過這類通常更偏向馬來人與印度人的菜系為主（客群也是），laksa、asam 或咖哩這類料理的湯水多，所以放大鍋或大塑料桶，小販拿個大勺幫你淋在飯上，可選擇蔬菜跟主菜或不選，旁邊立著的烤架上，不斷冒出烤雞腿、烤魚的香氣，我第一次注意到就是被香氣吸引，當然了，想吃這類食物，大熱天在戶外吃太煎熬了！同樣的食物大可找前幾篇有寫到的 nasi kandar、nasi lemak這類餐館來吃，環境較好，種類選擇多，價格也只比路邊的高少許。"}]},{"_type":"block","_key":"key-85-ifyqz","style":"normal","children":[{"_type":"span","_key":"key-83-96xmy","text":"怕大家誤解，並不是說路邊的馬來經濟飯不衛生，只是環境克難，台灣人普遍有種文化潔癖，覺得東南亞食物都不太衛生的刻板印象，事實上，馬來西亞有大量的美味街邊食物 street food，這也不敢吃那也不敢吃，我是覺得蠻可惜，"},{"_type":"span","_key":"key-84-wv1ta","text":"答應我，來大馬不要挑食好嗎","marks":["strong"]}]},{"_type":"block","_key":"key-87-4ks5s","style":"normal","children":[{"_type":"span","_key":"key-86-ldh53","text":"衛生方面，如果小販是穆斯林，除了受清真飲食戒律繁瑣規範，巧合地成為一道隱形的食安防護，馬來西亞的 Hala清真認證也相當的嚴格，到世界各地，只要是穆斯林賣的食物，如果又是普遍的清真族群食物，我完全不擔心其料理是否衛生，更不用怕他們添加有的沒的，儘管大口吃。"}]},{"_type":"block","_key":"key-89-uhe54","style":"normal","children":[{"_type":"span","_key":"key-88-5mhlm","text":"回想起曾在中國待過一段時日，也格外喜歡買回民賣的街邊烤串、蘭州拉麵館，回館餐廳是中國外食少數不必擔心食安的地方，西安回民街的水盆羊肉更是我會懷念的美味，當今蘭州牛肉拉麵館在馬來西亞大量出現，除了近幾年大量中國人移民馬來，想必清真飲食文化的親近性也是讓蘭州拉麵在大馬紮根的主因吧"}]},{"_type":"block","_key":"key-91-nwmld","style":"h3","children":[{"_type":"span","_key":"key-90-lbnqz","text":"• 不得不加倍努力"}]},{"_type":"block","_key":"key-93-y37ex","style":"normal","children":[{"_type":"span","_key":"key-92-hii26","text":"最後來聊個小趣事，我在找國泰茶室的地址時，猛然發現全馬來西亞不只一家，有的還掛上“新”國泰茶室之名。同樣的狀況還發生在找尋發記叉燒雲吞麵，全馬來西亞也到處各種發記、銘記、明記、祿記的餐廳，各個賣的都不同。"}]},{"_type":"block","_key":"key-101-8z034","style":"normal","children":[{"_type":"span","_key":"key-94-popum","text":"抱著這個困惑來到檳城，又遇到"},{"_type":"span","_key":"key-96-adr5j","text":"青屋蝦麵","marks":["key-95-9yi81"]},{"_type":"span","_key":"key-97-0fq6b","text":" 與 "},{"_type":"span","_key":"key-99-obpt0","text":"老青屋茶室裡的蝦麵","marks":["key-98-q5y0j"]},{"_type":"span","_key":"key-100-n7wsv","text":"，兩家是本店跟分店嗎？哪一家是必比登推薦？在地人又覺得哪一家好吃？問了很多當地人，也是眾說紛紜。"}],"markDefs":[{"_type":"link","_key":"key-95-9yi81","href":"https://maps.app.goo.gl/BUTp116xDCeddY8dA","blank":true},{"_type":"link","_key":"key-98-q5y0j","href":"https://maps.app.goo.gl/BvCZXAegrDaNq51g7","blank":true}]},{"_type":"block","_key":"key-103-r9ke7","style":"normal","children":[{"_type":"span","_key":"key-102-31d9h","text":"意外有個計程車司機，從另一個角度跟我分享他的觀點，原來馬來的商標專利法跟公司法，是以馬來語優先，因此，假如你新開一家雲吞麵，你可以用與知名的店一樣的中文名，只要你在註冊時的馬來文名稱有差別即可，難怪大馬這麼多中文名稱相同的館子。"}]},{"_type":"block","_key":"key-105-z7oqu","style":"normal","children":[{"_type":"span","_key":"key-104-jc4jr","text":"其次，馬來西亞餐廳的招牌是需要額外執照申請，招牌的法規也是偏向馬來文（如下圖，我查詢了相關規定，確實跟他講的差不多，台灣政府敢搞這樣傾斜式的規定絕對被罵爆）。"}]},{"_type":"image","_key":"key-106-avxcp","asset":{"_type":"reference","_ref":"01M59MGY6M725DWM1XAA486CSA","url":"/_emdash/api/media/file/01M59MGY6M725DWM1XAA486CSA.jpg"},"alt":"","caption":"這些律法帶給我更深刻的culture shock","alignment":"center"},{"_type":"block","_key":"key-108-x18er","style":"normal","children":[{"_type":"span","_key":"key-107-6gbk7","text":"司機用著福建話，不帶情緒、平靜地講述這件事，生活在台灣齊頭式平等社會的你我，大多數人的第一反應會覺得這樣很不平等，但轉念想想，大馬華人之所以是大馬華人，就是因為他們祖輩就選擇了落地生根，而非落葉歸根，適應、順應環境早就是族群的習慣與本能了，既然這是家庭的大家長訂的家規，也只能適應然後更加努力，司機後一句話印證我的想法，他意思是說：「不管青屋蝦麵與老青屋茶室裡的蝦麵誰先誰後，做的更好吃的，生意還是會最多」。"}]},{"_type":"image","_key":"key-109-c99x4","asset":{"_type":"reference","_ref":"01M59MGY9G8Y6DWM2PPXWHK8S0","url":"/_emdash/api/media/file/01M59MGY9G8Y6DWM2PPXWHK8S0.jpg"},"alt":"","caption":"左圖符合法規標準 馬來字比中文字的級數大   右圖很微妙，但伊斯蘭信仰者不會吃肉骨茶，所以字體打擦邊球也不會強硬糾正","alignment":"center"},{"_type":"htmlBlock","_key":"key-110-7don1","html":"[wpb_post_list_table]","originalBlockName":"core/shortcode"}]', '許多看似不理性不科學的食物混搭，在移民社會是很務實的折衷做法，也許是為了應消費者提出的需要，也可能是店家為增加銷售的行銷手法，又或是一個將異鄉食材由（陌）生到熟（悉）的必然摸索過程，非移民社會也會有，只是移民社會的飲食混搭更頻繁、更見怪不怪', 162, 'https://flavorinsight.com/wp-content/uploads/2024/10/aicast.mp3
3735360
audio/mpeg
');
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K5CXB1BNS9P1Z01N1HK3V', 'penang-hawker-ban-street-food', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-15T11:00:47.000Z', '2026-10-19 22:59:59', '2024-10-15T11:00:47.000Z', NULL, NULL, 13, '01M5AWZMZFCFNPJ9FAT2C42P75', NULL, 'zh-TW', '01M59K5CXB1BNS9P1Z01N1HK3V', '馬來筆記 Part4 再談馬來西亞飲食（中）', '{"id":"01M59MGY72YJ7NPZRPHKG12BMT","provider":"local","filename":"IMG_20240829_231214-scaled.jpg","mimeType":"image/jpeg","width":2560,"height":1920,"alt":"馬來筆記 Part4 再談馬來西亞飲食（中）","meta":{"storageKey":"01M59MGY72YJ7NPZRPHKG12BMT.jpg","caption":null,"blurhash":null,"dominantColor":null}}', '[{"_type":"block","_key":"key-2-i79k1","style":"h3","children":[{"_type":"span","_key":"key-1-djz9m","text":"• 中國好味道？"}]},{"_type":"block","_key":"key-4-xmnoi","style":"normal","children":[{"_type":"span","_key":"key-3-hxnrr","text":"前一篇講到中國蘭州拉麵，不只馬來西亞城市大量出現中國餐館品牌與小吃，全東南亞都會區都如此。台灣近年也湧現螺蛳粉、酸菜魚，會有這種現象，除了與中國政府從政策面去推廣具中國風味的特色飲食，尤其針對推向國際，社群媒體、短影音的推波助瀾也是主因，消費端的味蕾喜好有時只是跟風，我不多做評析，我真正想了解的還是大馬本地的餐飲從業者面對的問題。"}]},{"_type":"block","_key":"n6k45qoqw","style":"normal","children":[{"_type":"span","_key":"0kev3gtid","text":""}]},{"_type":"block","_key":"key-7-0pq7r","style":"normal","children":[{"_type":"span","_key":"key-5-ozu7r","text":"在中國近幾年的這一波餐飲品牌海外創業潮，平價連鎖餐飲與街邊小吃的界線是被模糊的，像是五谷魚粉、楊銘宇黃燜雞飯、蜜雪冰城、擼串、酸奶…等。\n"}]},{"_type":"block","_key":"njur2svw1","style":"normal","children":[{"_type":"span","_key":"key-6-1t8ds","text":"將傳統街邊的單品小吃拉入餐飲店的連鎖加盟與產銷模式下，對創業者有什麼好處？品牌的形象能更清晰，行銷與店內服務能做的更有區隔性，規模採購除了食材品質好掌控，最重要是成本再降低，可以做到更極致的薄利多銷，最鮮明的變化則是科技導入，長期降低了人力成本。這些以往可能在海底撈這種中高檔次的中國餐飲連鎖才玩得動，如今，即便只是普通中國餐館，都能玩轉，簡單講，開店要成功的三要素「品質、客流、成本」的難度都降低，彷彿中國電商一條龍的模式被移植來到餐飲業了。"}]},{"_type":"image","_key":"key-8-pk10f","asset":{"_ref":"01M59MGY7V6ZC1X91PSW4YRTTS","url":"/_emdash/api/media/file/01M59MGY7V6ZC1X91PSW4YRTTS.jpg"},"caption":"乳業產能過剩的中國酸奶輸出到海外，問了許多人，安慕希在大馬賣得並不好","alignment":"center"},{"_type":"block","_key":"key-10-sjb9s","style":"normal","children":[{"_type":"span","_key":"key-9-j4j3d","text":"模式之所以能有效，我認為還在於餐點品項的選擇與設計，皆是製作過程簡易的低難度料理，甚至適合以預製菜再重新復熱，也不會走味太多的類型，烹煮快、上菜快，又增加了翻桌率，像臭豆腐好了，台式炸臭豆腐就沒辦法用預製菜的方式，必須現炸，可湘式湯臭豆腐就很適合。"}]},{"_type":"block","_key":"3r9oi9o68","style":"normal","children":[{"_type":"span","_key":"1fqmsf41f","text":""}]},{"_type":"block","_key":"key-12-nkeow","style":"normal","children":[{"_type":"span","_key":"key-11-ojgu4","text":"乍看之下，面臨全球食品成本與人力成本的通膨，中國模式好像很行得通，但實際上體驗幾家後，發覺有致命的缺陷：「體驗感很貧乏」、「料理沒靈魂」。這些餐館的菜單看得出全力追求爆款，實際上是在透支日後的回購率，口味上也產生影響，一味迎合大眾，好吃的標準無意識被降低了，因為要讓位於快速的產銷流程，因此餐點便宜、口味尚可卻沒有靈魂，其次，再多網紅打卡式的裝潢，都掩蓋不了人群拉低的品味與體驗，試想今天你一家店沒幾個人是真正要坐下來品嚐食物，那氛圍就跟去大賣場是一樣的，熱鬧但淺薄。"}]},{"_type":"image","_key":"key-13-qwe6b","asset":{"_ref":"01M59MGY8B8AKQWXS2873E9RHA","url":"/_emdash/api/media/file/01M59MGY8B8AKQWXS2873E9RHA.jpg"},"caption":"中國自熱鍋擺在架上很好的位置但沒人買，盲目的產品輸出只是讓產能更加過剩，而不會真正解決問題","alignment":"center"},{"_type":"block","_key":"key-15-xjx4n","style":"normal","children":[{"_type":"span","_key":"key-14-u32ve","text":"這樣講可能有人不贊同，若你有去過賣冰飲品的蜜雪冰城 MIXUE ，應該了解它的人流是非常高的，價格也低廉到驚人，它具備了這波中國餐飲的海外連鎖的所有強項，然而你只需要去 google map，搜尋越南或是馬來西亞的蜜雪冰城，你會發現整體評分普通就算了，評價數異常的少，瑞幸咖啡也有同樣現象，有興趣的朋友可以嘗試開 google map，在新加坡搜尋luckin coffee ，從所有分店去一一觀察每一家評論的量化數據與內容分析（我在美股投資中也會以這類方式做調查），就應該能體會我要表達的，不知道是幸還不幸，馬來西亞就是瑞幸咖啡即將要大舉拓點的市場。"}]},{"_type":"image","_key":"key-16-13wvu","asset":{"_ref":"01M59MGY6NRRD2VQBHRYP64W7F","url":"/_emdash/api/media/file/01M59MGY6NRRD2VQBHRYP64W7F.jpg"},"caption":"4分以上的多是新開，4.8的則是極少數不用app即可購買的店(瑞幸咖啡必須註冊app才能你買)","alignment":"center"},{"_type":"block","_key":"key-18-d0vdv","style":"normal","children":[{"_type":"span","_key":"key-17-27hxq","text":"這就是體驗薄弱造成口碑行銷降低，選擇依賴短影音的社群行銷，就必須讓自己品牌的實體可見度夠，才能讓短影音的記憶被啟動而消費，因此，對於人流高的熱門地段需求反而高於傳統餐廳！否則變現率會較低，薄利多銷的模式也就崩解了。"}]},{"_type":"block","_key":"9o9e0yew2","style":"normal","children":[{"_type":"span","_key":"rx3xinpcs","text":""}]},{"_type":"block","_key":"key-20-xhgtp","style":"normal","children":[{"_type":"span","_key":"key-19-lp19e","text":"仔細一想，這種只顧現在、透支未來的經營，還蠻扭曲與病態，可能中國人就是愛卷吧，諸位有沒有過特地跑去很偏僻偏遠的地方，只為了吃某個美食的經驗？或是即使排了一小時的隊只為吃某個美食，也覺得超值的經驗？許多時候，一家店裡，都是來吃熱鬧還是來品嚐美食，會是截然不同的氛圍，所以營造吸引回頭客的情境，我認為才是能走長遠的關鍵。"}]},{"_type":"block","_key":"key-25-c0kj3","style":"normal","children":[{"_type":"span","_key":"key-21-h3t6t","text":"傳奇餐飲經理人 Danny Meyer 在"},{"_type":"span","_key":"key-23-y6me6","text":"他的書中","marks":["key-22-apf6o"]},{"_type":"span","_key":"key-24-79f23","text":"的這段話或許更精確點出中國連鎖餐飲的盲點："}],"markDefs":[{"_type":"link","_key":"key-22-apf6o","href":"https://www.books.com.tw/products/0010827097?gclid=Cj0KCQjw753rBRCVARIsANe3o45cfU9Nl11xHpQUHEVtXQzaofpjz-GsHbMfoX8Uj4xmK5XYTy1KcAwaAo9ZEALw_wcB","blank":true}]},{"_type":"block","_key":"al81muja9","style":"blockquote","children":[{"_type":"span","_key":"x8aq4p1h7","text":""}]},{"_type":"block","_key":"key-31-raose","style":"normal","children":[{"_type":"span","_key":"key-28-nf8x1","text":"這些是這幾年在東南亞以及這次在吉隆坡知名的茨廠街所見的感觸，"},{"_type":"span","_key":"key-29-65ksj","text":"馬來本地的餐飲創業者可能對加盟這些中國連鎖是要多深思熟慮，不宜照單全收","marks":["strong"]},{"_type":"span","_key":"key-30-rdq9o","text":"。另外這些中國餐廳的卷，如果排擠掉低價的本地餐飲業者，也會讓商圈攤商的多樣性降低，失去特色；更甚至讓當地人生計受影響，進一步感受主權焦慮與文化入侵，而對中國印象更差，飲食象徵了一個民族，假如你都是在 Garbage Out，那可能也只會得到 Garbage In。"}]},{"_type":"block","_key":"nlffitqwp","style":"normal","children":[{"_type":"span","_key":"zl9v0llsw","text":""}]},{"_type":"block","_key":"key-33-bbmy5","style":"normal","children":[{"_type":"span","_key":"key-32-z4cu8","text":"但也是有令我驚訝的中國連鎖，茶仙子與霸王茶姬CHAGEE算是成功地扎根大馬了，雖然說茶仙子還不斷\"致敬\"台灣手搖茶(避免被告用詞謹慎 但讀者應該懂我意思)，霸王茶姬CHAGEE則在整體體驗與口味上，已經走出自己的路，實話實說這個品牌有點厲害了。"}]},{"_type":"image","_key":"key-34-tepdl","asset":{"_ref":"01M59MGY72C9HEVBZH4AYPC2NR","url":"/_emdash/api/media/file/01M59MGY72C9HEVBZH4AYPC2NR.jpg"},"caption":"看到珍奶與阿里山，是否以為是台灣品牌呢？茶仙子是中國八馬茶業所創，很用力挪用各種台灣特色食材與手搖飲風味，在大馬頗受年輕人歡迎","alignment":"center"},{"_type":"block","_key":"key-36-vqkhl","style":"normal","children":[{"_type":"span","_key":"key-35-xl0z5","text":"題外話，去馬來西亞，記得吃看看鼎泰豐為伊斯蘭消費者推出的雞肉小籠包，是一種面對異國市場更謙遜的態度。"}]},{"_type":"block","_key":"key-38-z0rxu","style":"h3","children":[{"_type":"span","_key":"key-37-rn3ge","text":"• 料理有無國界"}]},{"_type":"block","_key":"key-40-afgvl","style":"normal","children":[{"_type":"span","_key":"key-39-2bp0k","text":"許多傳統飲食都面臨兩個難題，一是餐飲業的傳承困難，二是勞動力缺乏與昂貴，相對便宜的移工就成了多數餐飲業會選擇的方式。值得好奇的是移工掌廚，味道會變調嗎？"}]},{"_type":"block","_key":"6getjdhzi","style":"normal","children":[{"_type":"span","_key":"efjljw6z9","text":""}]},{"_type":"block","_key":"key-42-m7oxc","style":"normal","children":[{"_type":"span","_key":"key-41-3xdq8","text":"來分享我的親身體驗，先說這趟從檳城開始，我沒有吃到任何一家難吃的店（包括用Grab點的外賣），後續的城市也都吃的滿意極了，唯獨我到吉隆坡，由於很晚了，旅館 check-in 後就急忙往茨廠街去覓食，就此嘗到我來大馬吃到的唯二地雷食物（另一個雷在離境機場內），這是一家港式牛腩麵店，尊重店家我還是不說店名，總之剛入座，嗅覺靈敏的我聞到廚房飄過來的牛肉湯味就覺得慘了！可是外籍店員已經在桌邊準備幫我點餐，只好硬著頭皮點下去，有多難吃我就不描述了，總之後來我索性回飯店用 grab叫外賣沙嗲（satay）來療內傷，是的，這家牛腩麵是由外籍員工掌廚…"}]},{"_type":"image","_key":"key-43-duezx","asset":{"_ref":"01M59MGY7MAJ5YS81A4SKHCKQD","url":"/_emdash/api/media/file/01M59MGY7MAJ5YS81A4SKHCKQD.jpg"},"caption":"沙嗲也是不能錯過的美食，個人喜歡找沒賣豬肉沙爹的馬來人攤子，醬汁較醇厚","alignment":"center"},{"_type":"block","_key":"key-45-36pv1","style":"normal","children":[{"_type":"span","_key":"key-44-fzrhb","text":"事後吉隆坡朋友告訴我現在很多餐廳是給孟加拉或尼泊爾人掌廚，回憶牛腩麵員工們對話的語言，應該就是了，說真的，先前嚐過大馬各族裔做的菜，各有風味，讓我忽略了某些菜系是否仍應由最熟悉其風味特徵的族群製作？像是牛腩麵、雲吞麵這類港式食物是否在烹煮上，還是由味蕾偏好相近的華人來料理較好？"}]},{"_type":"block","_key":"key-47-z7yxn","style":"normal","children":[{"_type":"span","_key":"23nwt5jf2","text":""}]},{"_type":"block","_key":"x0yxw6ar0","style":"normal","children":[{"_type":"span","_key":"key-46-5tn6g","text":"我仍相信食物是跨國界，料理能在不同族群的手藝下產生新的風味，例如曾在一個新北越南小吃攤，吃到不輸正統名店的台式炸排骨，店家附上魚露沾醬，與越南風味的配菜，是一份讓我很驚喜的排骨飯，但如果是渴望一份正統台味排骨飯的消費者，想必會是極失望吧。"}]},{"_type":"block","_key":"key-49-u749b","style":"normal","children":[{"_type":"span","_key":"nixghbn88","text":""}]},{"_type":"block","_key":"gs6wlzwf8","style":"normal","children":[{"_type":"span","_key":"key-48-n9sow","text":"馬來西亞很多餐廳，試著找尋其間的平衡，例如位於八打靈再也的名店陳明記燒臘，在疫情結束後，開始聘用緬甸籍員工，在客戶中就引發兩極的爭論，有些 googlemap留言甚至我覺得跟料理無關，而是赤裸裸種族歧視😅，到後來老闆都多次出來回應澄清（下圖），廚師跟經理都是華人，緬甸員工只是擔任外場與外送包裝，但我相信這種質疑依舊會有。"}]},{"_type":"image","_key":"key-50-8j62m","asset":{"_ref":"01M59MGY9HPS52D3NHWENCQ48R","url":"/_emdash/api/media/file/01M59MGY9HPS52D3NHWENCQ48R.jpg"},"alignment":"center"},{"_type":"image","_key":"key-51-paay3","asset":{"_ref":"01M59MGY9H6JBA7VYYY01S9VCN","url":"/_emdash/api/media/file/01M59MGY9H6JBA7VYYY01S9VCN.jpg"},"alignment":"center"},{"_type":"block","_key":"key-55-3yl9i","style":"normal","children":[{"_type":"span","_key":"key-52-tmoe8","text":"檳城為什麼能讓我不踩雷？當地朋友告訴我，原來檳城餐飲界有不成文的公約，檳城知名的特色食物，是禁止交給外籍勞工掌廚（下圖），這展現了檳城人對傳統風味的自豪與保護，而在吉隆坡這樣國際化的現代城市，選擇將餐飲交予商業自由主義，在這個找尋平衡的過程，可能有些店失去舊味道與舊客戶，還尚未找尋到新味道與新客戶前就被市場淘汰了，運氣好的，也許就成為某種創新料理的開拓者。"},{"_type":"span","_key":"key-53-egtau","text":"下一篇我會提到上個世紀初，馬來西亞海南移民作為外籍勞工掌廚，用廚藝贏得肯定並開創出一個新菜系的故事","marks":["strong"]},{"_type":"span","_key":"key-54-ba8y7","text":"。"}]},{"_type":"image","_key":"key-56-muyti","asset":{"_ref":"01M59MGY6M5WWBMZGTB0RKKRFP","url":"/_emdash/api/media/file/01M59MGY6M5WWBMZGTB0RKKRFP.png"},"alignment":"center"},{"_type":"block","_key":"key-58-icdis","style":"normal","children":[{"_type":"span","_key":"key-57-z1p8y","text":"如果你渴望嘗試新奇、創新的飲食，吉隆坡很不錯，如同新加坡，有大量國際化的風味激盪，追求成熟雋永的老味道，你得往不那麼熱鬧的城市去。"}]},{"_type":"htmlBlock","_key":"key-59-02gx9","html":"[wpb_post_list_table]"}]', '檳城不成文的規定是知名的特色食物，是禁止交給外籍勞工掌廚，這展現了檳城人對傳統風味的自豪與保護，而在吉隆坡這樣國際化的現代城市，選擇將餐飲交予商業自由主義', 88, NULL);
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K5H2JCZH0RP0E68ASW9ZV', 'ramly-burger-hainan-roots', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-17T06:46:11.000Z', '2026-10-20T04:05:27.028Z', '2024-10-17T06:46:11.000Z', NULL, NULL, 3, '01M5BQRH1KJ79J1DDX836GRMAW', NULL, 'zh-TW', '01M59K5H2JCZH0RP0E68ASW9ZV', '馬來筆記 Part4 再談馬來西亞飲食（下）', '{"id":"01M59MGY8NB2NQ9JBCMVEEDBSG","provider":"local","filename":"IMG_20240903_083632-scaled.jpg","mimeType":"image/jpeg","width":2560,"height":2116,"alt":"馬來筆記 Part4 再談馬來西亞飲食（下）","meta":{"storageKey":"01M59MGY8NB2NQ9JBCMVEEDBSG.jpg","caption":null,"blurhash":null,"dominantColor":null}}', '[{"_type":"block","_key":"key-2-rcfho","style":"h3","children":[{"_type":"span","_key":"key-1-0zvju","text":"• 被低估的料理之一：海南菜"}]},{"_type":"block","_key":"key-4-lbbdd","style":"normal","children":[{"_type":"span","_key":"key-3-rpdao","text":"文章篇幅很長，下面是AI生成的摘要聲音檔，可聽聽，有興趣再讀全文"}]},{"_type":"embed","_key":"key-5-4af87","url":"/_emdash/api/media/file/01M59MGY6QN0VQGT8Z1NR6GXCS.mp3","provider":"audio","html":"<figure class=\"wp-block-audio\"><audio controls src=\"/_emdash/api/media/file/01M59MGY6QN0VQGT8Z1NR6GXCS.mp3\"></audio></figure>"},{"_type":"block","_key":"key-7-7vqj1","style":"normal","children":[{"_type":"span","_key":"key-6-of9c9","text":"作為一名餐飲產業和餐飲文化研究者，我總是喜歡探索各種菜系的起源與演變。這種追溯 culinary lineage 的過程，每每讓我聯想到生物學家研究古人類族群如何遷徙與期間迸發的基因多樣性。每當接觸一個新的菜系，就像生物學家發現了一個新的物種一樣興奮。這一趟旅行遇到的新菜系就是馬來海南菜！"}]},{"_type":"block","_key":"key-9-q6kbe","style":"normal","children":[{"_type":"span","_key":"key-8-giwqz","text":"海南人在 19 世紀末 80 年代開始大量移民，高峰則是 20 世紀初，跟英國殖民統治馬來亞的時期重疊（1824-1957 年），相較於閩粵客家等華人的移民高峰期，海南人將近晚了一百年，沒太多出人頭地機會的他們，只好在英國殖民者的家庭、俱樂部和酒店中擔任傭人、廚師或服務生。"}]},{"_type":"block","_key":"key-11-orerx","style":"normal","children":[{"_type":"span","_key":"key-10-cuvu3","text":"回顧典籍，我察覺這些海南移民的烹飪天賦實在很高，藉著觀察英國人的飲食與烹飪，他們不僅能模仿出道地的料理來換取殖民者的信任，後期還從當地食材加上家鄉的烹飪技巧，創造出新的馬來海南菜系。最令人驚艷的是，這個菜系不僅保留了海南菜的精髓，還吸收了馬來飲食、英國口味，甚至是西方飲食文化的元素，形成了一種獨特的、混合文化式的料理菜系（fusion cuisine）。"}]},{"_type":"image","_key":"key-12-ygzuf","asset":{"_type":"reference","_ref":"01M59MGY9HQVD6GR5JZ63XNGFG","url":"/_emdash/api/media/file/01M59MGY9HQVD6GR5JZ63XNGFG.jpg"},"alt":"","caption":"海南人在普遍認知中廚藝很強，就像檳城觀音廟旁的海南滷麵，號稱海南，但福建滷麵的味道極純粹正統，絲毫嚐不出海南混合菜系的味道，那為何取名海南呢？將海南人廚師的招牌亮出來就能讓其他族裔信服好吃","alignment":"center"},{"_type":"block","_key":"key-14-9lv42","style":"normal","children":[{"_type":"span","_key":"key-13-mu0ch","text":"瞭解到這個背景讓我聯想到，17-18 世紀時的美國路易斯安那州仍由法國人統治，非洲黑人在當農奴與傭人時，學會了法餐與西班牙菜的料理手法，融入了非洲料理，就產生了美國紐奧良的克里奧爾菜（Creole Cuisine）與卡津菜（Cajun Cuisine），甚至是後來更廣為人知的美國南方靈魂食物（Soul Food）"}]},{"_type":"image","_key":"key-15-g3sy9","asset":{"_type":"reference","_ref":"01M59MGY6WHT9CBYVDB7S2W1KN","url":"/_emdash/api/media/file/01M59MGY6WHT9CBYVDB7S2W1KN.jpg"},"alt":"","caption":"lighthouse餐廳的海南雞排","alignment":"center"},{"_type":"block","_key":"key-22-slkbs","style":"normal","children":[{"_type":"span","_key":"key-16-nyesi","text":"馬來海南菜系的特點之一是其對西式料理的創新詮釋。「海南式西餐」就是這種創新的絕佳例證，它融合了英國殖民時期的影響，創造出如海南雞排、海南豬排、海南咖啡、咖央醬、蒸麵包、炸魚薯條…等新式料理，以及"},{"_type":"span","_key":"key-18-prqw5","text":"前面介紹過的 roti babi","marks":["key-17-ychzz"]},{"_type":"span","_key":"key-19-fbdbe","text":"。這些菜品常常搭配紅毛醬油（伍斯特醬）、褐醬（ HP 醬）。題外話，說一個上海菜，"},{"_type":"span","_key":"key-20-mlhv2","text":"在上個世紀初歐美各國租借時期，也曾出現過一道可稱為「上海式西餐」的上海豬排","marks":["strong"]},{"_type":"span","_key":"key-21-qzoki","text":"，跟海南豬排相似，都是將西式的豬排用中式烹調方法重新詮釋，對烹飪有興趣的朋友可去查查兩者食譜的異同。"}],"markDefs":[{"_type":"link","_key":"key-17-ychzz","href":"/posts/penangtotainan","blank":true}]},{"_type":"image","_key":"key-23-he0x4","asset":{"_type":"reference","_ref":"01M59MGY6V2Y78T0YQBYMWPGV8","url":"/_emdash/api/media/file/01M59MGY6V2Y78T0YQBYMWPGV8.jpg"},"alt":"","caption":"海南麵","alignment":"center"},{"_type":"block","_key":"key-28-46sd7","style":"normal","children":[{"_type":"span","_key":"key-24-gs1ni","text":"馬來海南菜系的另一個特點是中菜的馬來化，其代表食物許多人都知道，就是海南雞飯，看似簡單的菜餚，實則蘊含深厚的烹飪技藝，其根源可以追溯到海南島的名菜文昌雞，"},{"_type":"span","_key":"key-26-z9dnq","text":"陳靜宜老師的書中","marks":["key-25-954m4"]},{"_type":"span","_key":"key-27-je8vf","text":"有詳盡的介紹，加上個人很不喜歡吃海南雞飯，我就不贅述了，其他還有海南麵、海南豆腐…等。"}],"markDefs":[{"_type":"link","_key":"key-25-954m4","href":"https://www.books.com.tw/products/0010785203?sloc=main","blank":true}]},{"_type":"block","_key":"key-30-e4khp","style":"normal","children":[{"_type":"span","_key":"key-29-lt988","text":"馬來海南菜系正面臨著傳承的危機。許多傳統的馬來海南菜色可能在未來逐漸消失。馬來海南菜系並沒有像美國紐奧良的克里奧爾菜（Creole Cuisine）與卡津菜（Cajun Cuisine）那樣，有足夠多且凝聚的非裔美國人社群當基底，連傳承都困難，就更遑論新一代的創新接棒。"}]},{"_type":"block","_key":"key-32-thl09","style":"normal","children":[{"_type":"span","_key":"key-31-qtbhe","text":"馬來西亞觀光政策與文化推廣上，也忽視這個菜系的獨特性與觀光潛力，個人覺得頗可惜，大馬政府應更有意識地給予這個族群文化發展的資源，將馬來海南菜拉高到美國南方靈魂食物的層次去重視，新加坡尚未意識到這個菜系的整體脈絡，才有機會在與新加坡不斷競爭同名稱的食物歸屬中勝出，Hainanese Soul Food 對於觀光客來說會是個好故事。"}]},{"_type":"block","_key":"key-34-gupfd","style":"blockquote","children":[{"_type":"span","_key":"key-33-xbmjy","text":""}]},{"_type":"image","_key":"key-35-ejfel","asset":{"_type":"reference","_ref":"01M59MGY6SHKX1T3GVZRTSNCE6","url":"/_emdash/api/media/file/01M59MGY6SHKX1T3GVZRTSNCE6.jpg"},"alt":"海南雞排","alignment":"center"},{"_type":"block","_key":"key-37-5zjuo","style":"normal","children":[{"_type":"span","_key":"key-36-o2ga0","text":"至少令人欣慰的是，馬來海南菜系的創新成果已經深深地融入了馬來西亞的飲食文化中。即使未來馬來西亞的正統海南餐館可能變得稀少，但他們所創造的許多菜色依舊存在於其他族裔的餐桌上，繼續被人們所喜愛和享用。例如，在茶餐廳中常見的海南蒸麵包、海南咖啡、海南雞扒等，已經成為了跨越族裔界限的受歡迎美食。這些菜品不再僅僅代表海南族群，而是成為連結不同族群的紐帶。"}]},{"_type":"block","_key":"key-39-s8tx2","style":"normal","children":[{"_type":"span","_key":"key-38-0exi8","text":"也許，文化的傳承並非只有一種模式。有時，看似是消逝，實則是以另一種形式的存在和延續。","marks":["strong"]}]},{"_type":"image","_key":"key-40-7tqyy","asset":{"_type":"reference","_ref":"01M59MGY6SHZQR7M33QX1GBSZB","url":"/_emdash/api/media/file/01M59MGY6SHZQR7M33QX1GBSZB.jpg"},"alt":"","caption":"鎰記茶餐館","alignment":"center"},{"_type":"block","_key":"key-42-0jhkt","style":"normal","children":[{"_type":"span","_key":"key-41-omkr4","text":"最後推薦幾家海南餐廳及茶餐室，個人實在蠻喜愛巴生港地區，此地的海南族群明顯較有活力，老店的傳承看起來也較沒問題，可能有海南人群聚村落有助於認同鞏固、文化維繫，此地海南餐館刻意提供大馬三大族群都能吃的餐點則是生存的秘訣；檳城的海南族群較散居，相比其他華人族裔的文化，海南似乎消融中；吉隆坡的鎰記茶餐館，營運模式與環境就像現代餐廳，吸引許多國際觀光客，口味精緻，未來一定會再訪。"}]},{"_type":"block","_key":"key-46-p3yhz","style":"normal","children":[{"_type":"span","_key":"key-43-cc5rr","text":"巴生：新國泰海南茶餐室、偆園海南咖啡 1956\n"},{"_type":"span","_key":"key-44-jaabq","text":"吉隆坡：鎰記茶餐館、新記餐室、安邦中西茶餐室\n"},{"_type":"span","_key":"key-45-uqns5","text":"檳城：海安飯店、The Lighthouse Cafe"}]},{"_type":"block","_key":"key-48-lu938","style":"h3","children":[{"_type":"span","_key":"key-47-cv07f","text":"• 被低估的料理之二：Ramly burger"}]},{"_type":"block","_key":"key-55-q4d8x","style":"normal","children":[{"_type":"span","_key":"key-49-77qgc","text":"特地去馬來西亞吃漢堡聽起來是件很奇怪的事對吧？幾年前我也曾這麼想，首先從漢堡發源地的美國開始談起吧，紐約時報在前幾個月有篇引發熱門討論的專題報導「"},{"_type":"span","_key":"key-50-gfacr","text":"漢堡是美國的肖像（The Burger Is a Portrait of America）","marks":["strong"]},{"_type":"span","_key":"key-51-mnjlm","text":"」（"},{"_type":"span","_key":"key-53-kmfhb","text":"點此閱讀","marks":["key-52-jk9gs"]},{"_type":"span","_key":"key-54-uk6e1","text":"），作為美國象徵性與獨創性的食物，漢堡充滿了造就美國的文化成分：地區傳統、移民靈感、深厚的歷史，該報導列舉了 11 家美國各地餐廳的漢堡，來反映當前這種美式食物的現況與未來的可能性，其中幾家蠻顛覆一般大眾對美式漢堡的想像。如紐約市的奈及利亞餐廳Akara House 的素食漢堡、西雅圖 Ox Burger 餐廳的寮國風味漢堡，以及費城金寶餐廳的馬來西亞 Ramly burger，馬來西亞 Ramly burger赫然在其中。"}],"markDefs":[{"_type":"link","_key":"key-52-jk9gs","href":"https://archive.is/ZmnMA","blank":true}]},{"_type":"block","_key":"key-57-ctc6k","style":"normal","children":[{"_type":"span","_key":"key-56-ynr19","text":"然而如果你問馬來西亞人，就會知道這是他們從小吃到大的食物，Ramly burger 在大馬已經發展了將近半世紀，已成為獨樹一幟的街頭飲食成員。"}]},{"_type":"block","_key":"key-59-zt1pa","style":"normal","children":[{"_type":"span","_key":"key-58-cqzn5","text":"Ramly burger的故事可以追溯到1979年，當時的創始人Ramly bin Mokni 還是一個超市切肉工人，發覺市面上沒有符合穆斯林食用標準的漢堡肉，於是他與妻子在吉隆坡開設了第一個漢堡攤。他們獨特的烹飪方法和口味，很快就贏得了顧客的青睞，逐漸發展成為一個成功的品牌。隨著時間的推移，Ramly burger不僅成為了街頭小吃，更發展成為一個大型冷凍食品公司與馬來西亞最大的肉類加工商之一。Ramly burger 雖然發展成為了一個大型食品加工品牌，但每一個使用其漢堡肉餅的街頭漢堡攤商，都有自己獨特的秘方。與美國的漢堡文化較重視標準化不同，相比之下，馬來西亞的漢堡文化則更加強調個性化和區域特色，所以即便發展至今這麼多年，比起發展成連鎖快餐店，Ramly burger 依舊維持著 Street Food 食物的本色，在夜市攤子與夜晚的街頭攤車，更為活躍！"}]},{"_type":"image","_key":"key-60-imi4p","asset":{"_type":"reference","_ref":"01M59MGY827CRBGPRTWQCZDS3X","url":"/_emdash/api/media/file/01M59MGY827CRBGPRTWQCZDS3X.jpg"},"alt":"","caption":"脆雞漢堡","alignment":"center"},{"_type":"block","_key":"key-62-jstey","style":"normal","children":[{"_type":"span","_key":"key-61-41xaa","text":"這也是帶給我最大的喜悅與痛苦，喜悅是每一家街頭 Ramly burger 都有特色鮮明，牛肉、羊肉、脆皮雞腿肉、蛋包、起司與獨特的辣醬，痛苦的是 Ramly burger 絕大多數都在晚間或深夜營業，我連續好幾天在晚上十點後滿懷罪惡感吃高熱量的漢堡😅"}]},{"_type":"image","_key":"key-63-fbudw","asset":{"_type":"reference","_ref":"01M59MGY7V2P37AGAMCVX7A9K8","url":"/_emdash/api/media/file/01M59MGY7V2P37AGAMCVX7A9K8.jpg"},"alt":"","caption":"羊肉漢堡","alignment":"center"},{"_type":"block","_key":"key-65-kjeh4","style":"normal","children":[{"_type":"span","_key":"key-64-rmzug","text":"多數的Ramly burger 廚師會將漢堡肉餅裹在一層薄薄的煎蛋中，這不僅鎖住了肉汁，還增添了一層口感。對我來說還有一個優點，因為多數 Ramly burger 都在較偏僻的路邊，我都選擇直接叫 Grab外送，省得深夜大老遠去排隊等候，蛋包包覆漢堡肉能讓我在拿到漢堡時，與現做現吃的差異較少。另外不管你點何種肉，記得都要選擇 double special （肉蛋加倍），反正都這麼晚吃宵夜了，就吃好吃滿最重要（狀態顯示為自暴自棄）。"}]},{"_type":"image","_key":"key-66-im99r","asset":{"_type":"reference","_ref":"01M59MGY99CD0VR9XR466CDTMX","url":"/_emdash/api/media/file/01M59MGY99CD0VR9XR466CDTMX.jpg"},"alt":"","alignment":"center"},{"_type":"block","_key":"key-68-vruct","style":"normal","children":[{"_type":"span","_key":"key-67-bo416","text":"近年來，隨著全球興起街頭食品文化和餐車創業潮，Ramly burger 再次迎來了新的發展。加上馬來政府對小販與餐車創業的法令限制放寬。許多年輕人開始投入 Ramly burger 創業，新一代大馬創業者的漢堡，就朝向更精緻，並提高較多美式正統風味的優點元素，例如焦化洋蔥。"}]},{"_type":"block","_key":"key-71-c7o52","style":"normal","children":[{"_type":"span","_key":"key-69-30f59","text":"這些發展變遷蠻有意思，假如回頭看台灣本土的漢堡文化，使自於中美斷交後，1979 年創立的台北天母的茉莉漢堡或 1980 年的女王漢堡，是第一波本土漢堡興起，Ramly burger 的創始也是源自 1979 年，然而其後台灣的漢堡創業，很長一段時間都被國際連鎖快餐業者壓制，本土漢堡藏在早餐店中緩步發展，Ramly burger 則沒受到國際連鎖餐飲的擠壓（因美式連鎖餐廳上世紀在馬來西亞受到的文化猜忌比較多，阻礙其展店傳播速度），才成功的在本地紮根，形成了獨特的飲食文化。\n"},{"_type":"span","_key":"key-70-2zbil","text":"真正重新打出台灣本土漢堡創業潮的是 2008 年的發福廚房，作為第二波，但漢堡仍沒有獨立意識，而是與義大利麵麵等輕食一起呈現，但口味上已開始嘗試橋接台味風格與美式風格。"}]},{"_type":"block","_key":"key-73-55mwj","style":"normal","children":[{"_type":"span","_key":"key-72-sxdhb","text":"2010 後隨著經濟景氣持續低迷與社群網絡興起，開始第三波浪潮至今（包括餐車創業風），台灣創業者很迅速跟上 Shakeshake 這些美國漢堡的新浪潮，更多漢堡專賣店興起，從各式各樣的口味需求切入，迸發出許多本土創意之餘，像是對麵包與漢堡肉有更精緻化的提升，漢堡在台灣也終於被認真視為一道料理了。"}]},{"_type":"block","_key":"key-76-u1ku4","style":"normal","children":[{"_type":"span","_key":"key-74-y3j9b","text":"我很期望未來也能有一款台灣風味的漢堡，能像馬來西亞的Ramly burger 去嘗試在美國消費市場立足，相信以台灣人對食物的熱情，這一天應該不會太久遠。\n"},{"_type":"span","_key":"key-75-se8w6","text":"從美國到大馬，又講到台灣，說了這麼多，只需知道：Ramly burger 絕對是你去馬來西亞不可錯過的街頭食物，記得 double special 更美味。"}]},{"_type":"block","_key":"key-78-seeua","style":"h3","children":[{"_type":"span","_key":"key-77-rk3hh","text":"• 童年comfort food的記憶"}]},{"_type":"block","_key":"key-80-p4gwh","style":"normal","children":[{"_type":"span","_key":"key-79-i25qw","text":"你我一生嚐過各種食物的味道，如果你嘗試盡可能回憶童年時期的味覺記憶，多數人食物記憶的基礎都會是各種甜味，酸、苦、辣、鹹等味覺並不在其中，除了因為孩童的味覺發展尚未成熟，甜味本身還連結到舒適、安全和溫暖等感受，當然，如果你是六歲就吃大蒜配香腸、七歲愛吃泡菜與臭豆腐、八歲無辣不歡的神童，就不在此論述。"}]},{"_type":"block","_key":"key-82-7k0i3","style":"normal","children":[{"_type":"span","_key":"key-81-ye8uw","text":"我的童年味覺記憶也是帶著八、九分甜，為日本人幫傭過的外婆煎的玉子燒或荷包蛋，總是糖加比鹽多，祖父母做的年夜飯，我每年都還沒吃完飯，就去偷舀一碗客家紅白湯圓甜湯，各家長輩來串門時，總會帶著的各種吃食，像是熱呼呼的米香、茯苓糕、狀元糕、雞蛋糕、車輪餅、日治時代營業至今的天天饅頭，我最期待的則是蓬鬆帶著花生香氣的麵粉粿（麵粉粿是我中部家鄉台語的稱呼，又被稱為大麥煎、麥仔煎、麵粉煎）。"}]},{"_type":"block","_key":"key-84-jglp9","style":"normal","children":[{"_type":"span","_key":"key-83-o4r3a","text":"還未出發到馬來西亞前，網路搜尋怡保資訊時，就注意到他們稱為大塊麵的食物，外觀看起來就是我小時候很喜歡的麵粉粿，以為是台灣人過去賣的，但認真一看發現不對呀，怎麼好像是當地行之有年的食物？搜尋檳城時，再度看到同一種食物，只是被稱為曼煎糕，勾起我的好奇心。"}]},{"_type":"block","_key":"key-86-9jmym","style":"normal","children":[{"_type":"span","_key":"key-85-w3vzi","text":"查了維基百科，上面寫曼煎糕是來自福建的食物，我腦海浮現大大的蛤？ 孩童時，曾問過長輩，麵粉粿是哪裡來的食物？因為除了花生跟糖粉是中國元素，它的餅咀嚼起來充滿西方感，跟中式糕點不同，年幼的我沒想的那麼深，只是本能的覺得不一樣，比狀元糕這類中式糕點好吃，長輩回答我：「以前麵粉很貴，是美軍援台時代進口大量麵粉，台灣就有人把麵粉拿來變出麵粉粿」，我就這麼相信了三十年，現在你維基百科跟我說麵粉粿“自古以來“屬於福建不可分割的一部分！？坦白說，當下我真的質疑這條目的真實性，是不是中國小粉紅編寫的？😂"}]},{"_type":"block","_key":"key-88-z8d1t","style":"normal","children":[{"_type":"span","_key":"key-87-wnxc5","text":"在大馬的旅途中，抱持著這個疑問，實際品嚐與觀察曼煎粿以及當前大馬較流行的薄片式曼煎粿，兩者就像是西式鬆餅變化到可麗餅，薄片式曼煎粿就只有一層極薄且酥脆的餅皮，稍微彎曲摺疊，放入較有顆粒感的碎花生、糖粉的內餡，有些還會加上玉米粒等配料增加豐富程度，完全顛覆我習以為常的傳統曼煎粿，由一大塊厚實的餅皮去分切食用，題外話我覺得怡保大塊麵的稱呼很貼切，我從小常幻想獨自吃完整的、沒切開的麵粉粿，可對孩子來說那份量太大塊了！"}]},{"_type":"image","_key":"key-89-q8g91","asset":{"_type":"reference","_ref":"01M59MGY9C0N1W1MM3NQH5XCKS","url":"/_emdash/api/media/file/01M59MGY9C0N1W1MM3NQH5XCKS.jpg"},"alt":"","caption":"薄片式曼煎粿","alignment":"center"},{"_type":"block","_key":"key-91-lez0g","style":"normal","children":[{"_type":"span","_key":"key-90-n5f2k","text":"麵粉粿、曼煎粿，無論你所在的地區如何稱呼它，在大馬親身吃過，並親眼看到它的眾多變化後，我相信它確實源自福建，而且是百年以上的的舊年代，而非半世紀內的現代產物，原因就在於傳統做法與口味的曼煎粿，如果是新食物，不太可能在半世紀擴散到港、澳、台、新、馬、印尼等地，甚至馬來西亞偏僻的鄉間也有，並且味道沒有改變，假如是半世紀內流行而擴散到這麼大範圍，那報導與文獻記載會很多，可實際上沒有，此外薄片式曼煎粿也明顯不是新近幾年才出現的創新，調理的成熟度與攤販的普及，都顯示這個食物已落地大馬非常久遠！"}]},{"_type":"block","_key":"key-96-aokti","style":"normal","children":[{"_type":"span","_key":"key-92-74eip","text":"那為何我（歷經日治時期）的長輩會認為麵粉粿是美援時代才開始有的食物呢？看到陳玉箴教授對日治時期臺灣烘焙產業的精彩研究 "},{"_type":"span","_key":"key-94-mriaj","text":"（文章連結）","marks":["key-93-3q5tm"]},{"_type":"span","_key":"key-95-7rba0","text":"，隱約給了我些想法。"}],"markDefs":[{"_type":"link","_key":"key-93-3q5tm","href":"https://talk.ltn.com.tw/article/breakingnews/3804799","blank":true}]},{"_type":"block","_key":"key-98-2m7x0","style":"normal","children":[{"_type":"span","_key":"key-97-1mz71","text":"無論日治前後，小麥在台灣栽種都不流行，種稻還是主流，此外品質問題，麵粉都傾向進口。日治前，以節慶用的漢餅為主，西式麵包罕見且貴，日治後，日本帶來了和果子與西式麵包的文化，然麵包依舊並非日常食物，而是非庶民的特定情境式消費，不過日治中期到中日開戰前的富庶，民眾消費力顯著提高，給了許多台灣飲食發展創新的土壤，一些知名的精緻台菜也在這階段出現，此時台灣可能已經有些地方的福建移民，有製作麵粉粿，不過這種食物在日治時代很難流行，因為麵粉粿較粗曠的口味與外觀，不具備當時日本明治或大正時代所推崇的西洋化文明飲食的特徵，有消費力的不願意吃，願意吃的可能沒消費力，且跟漢餅的消費族群的習慣口味差別太大，所以我的長輩非常有可能根本沒看過麵粉粿（但她在日治時代就嚐過雞蛋糕、銅鑼燒）。"}]},{"_type":"block","_key":"key-102-61l1i","style":"normal","children":[{"_type":"span","_key":"key-99-1zffx","text":"爾後戰爭開始直到國民黨來台初期，台灣經濟一直是處於被高度壓榨的狀況，社會普遍更難有餘裕去消費甜點，此處台灣大眾飲食有 20 多年的紀錄是支離破碎甚至消費倒退，所以"},{"_type":"span","_key":"key-100-of39s","text":"能夠從 1937 年以前存活至今的台灣糕餅品牌都非常了不起，值得我們多珍惜","marks":["strong"]},{"_type":"span","_key":"key-101-tuz80","text":"。"}]},{"_type":"block","_key":"key-104-s0sm4","style":"normal","children":[{"_type":"span","_key":"key-103-psqmo","text":"直到1960年前後美國開始大量援助麵粉給台灣，加上許多經濟扶持，許多外省人飲食、麵點、西式麵包蛋糕也是在此時開始迸發，甚至政府更鼓勵多吃麵少吃飯，讓更多的米能外銷賺取外匯，麵粉粿就是在此時，由福建移民重拾爐灶，開始製作並販售，並以很快的速度擴散到全台灣各地，讓許多台灣人第一次認識與品嚐，我的長輩可能就是因此以為這是美援時期產生的台灣本土新食物。"}]},{"_type":"block","_key":"key-106-x8x66","style":"normal","children":[{"_type":"span","_key":"key-105-nf644","text":"雖然只是個人推敲，但我嘗試搜尋目前台灣的麵粉粿老店或攤子，最早開業的確實就是五十多年、不超過六十年，再更之前是找尋不到痕跡的，麵粉粿在台灣的發展歷史是呈現不連續的樣態，但這個食物絕對存在更早，因為麵粉粿在澳門稱之為冷糕，最老的店是創業自1949年，若當時冷糕沒有在民間有一定的認知度與消費需求，當時的創辦人也不會想藉此創業，若有達賢知曉麵粉粿在更早期台灣或他國歷史中的記載，煩請與我分享。"}]},{"_type":"block","_key":"key-108-zj6vo","style":"normal","children":[{"_type":"span","_key":"key-107-wyynk","text":"回頭來說馬來西亞的曼煎粿，除了維持傳統做法，還跟馬來族裔、印度族裔的文化交匯，產生新的風貌。"}]},{"_type":"block","_key":"key-110-jpvcb","style":"normal","children":[{"_type":"span","_key":"key-109-bi4xr","text":"印度移民帶來一種稱為 Apom 的煎餅，受到曼煎粿許多影響，多數看到都是甜的 Apom manis（甜煎餅），還會配上香蕉等水果，一些路邊的嘛嘛檔（mamak）有賣原味 Apom 加蛋再抹上辣醬，風味很類似我們的早餐蛋餅，傳統的 Apom 尺寸都很迷你，要碼一口大小或是蛋餅皮大小，不同於與曼煎粿/麵粉粿那種大鍋尺寸，但有趣的點也在此，Apom 有稱為 Apom Balik（摺疊煎餅）的大鍋製作版本，可印度人傳統製作時並未使用大鍋，而曼煎粿的馬來語稱為Apam Balik，Apom Balik 明顯是習自 Apam Balik（曼煎粿）的後來產物。"}]},{"_type":"block","_key":"key-112-4dvmy","style":"normal","children":[{"_type":"span","_key":"key-111-4orl1","text":"曼煎粿對 Apom 的影響還包括同樣使用白糖粉與花生碎的配方，兩者最大的差別點在於麵糊的成分，曼煎粿是麵粉、雞蛋、牛奶（就像蛋糕），Apom 則是米粉、椰漿、椰絲，此外曼煎粿的麵糊有經過發酵，所以煎烤時會膨脹膨鬆，Apom 則沒有經過發酵，會更酥脆，常邊吃邊掉碎屑。"}]},{"_type":"block","_key":"key-114-6mi99","style":"normal","children":[{"_type":"span","_key":"key-113-8cynl","text":"如果你還記得文章開始我提到不同於福建傳統的薄片式的曼煎粿，就我吃到的口感，麵糊的成分是正統的曼煎粿，可並未經過發酵，且煎烤時抹的麵糊極薄，使用小型鐵鑄模具，追求酥脆口感，試圖把曼煎粿做的如同Apom！"}]},{"_type":"block","_key":"key-116-von9k","style":"normal","children":[{"_type":"span","_key":"key-115-9nmqo","text":"這就是馬來西亞複雜又有趣的又一個例子，福建移民從原鄉帶來曼煎粿，受馬來、印度影響，產生薄脆小巧版本；而印度移民從原鄉帶來 Apom，被馬來化同時也學了華人的烹煮方式與調味，學會華人用大鍋做大餅，多元移民社會下，這些創新自然而然地就發生了。當然，你我熟悉的傳統曼煎粿也依舊存在於街頭、夜市與茶餐室，馬來西亞也仍然有人販售印度傳統的 Apom。"}]},{"_type":"image","_key":"key-117-vqpum","asset":{"_type":"reference","_ref":"01M59MGY6R4ZV07YSQ7VBVWDQT","url":"/_emdash/api/media/file/01M59MGY6R4ZV07YSQ7VBVWDQT.jpg"},"alt":"","caption":"檳城傳統糕餅店內販售的零食，不禁想到我們習慣的蝦味先該不會也是歷史悠久且傳播地域很廣的食物吧？","alignment":"center"},{"_type":"block","_key":"key-119-xpjew","style":"normal","children":[{"_type":"span","_key":"key-118-g154i","text":"行筆至此，深感味覺的形成遠比你我想的更複雜，不僅是個人偏好，也帶著家庭環境的塑造，更還有社會變遷脈絡與大時代國族的傳承；也恍然明白，隨著自己年歲增長，明明是刻意越來越少吃糕點甜點，可偏偏每當看到台灣路邊販售傳統糕點的小攤子，總是抱著莫名的情緒買下（像是基隆的名古屋日式甜點，每次在台北市區看到攤車都爆買），並非味蕾渴望其滋味，而是一種希望飲食傳承能延續下去、不捨其凋零的支持，年幼時帶著這些食物來串門的長輩們，除了對我的關愛，也許也是類似的心境吧。"}]},{"_type":"htmlBlock","_key":"key-120-y80p0","html":"[wpb_post_list_table]","originalBlockName":"core/shortcode"}]', '馬來海南菜系的創新成果已經深深地融入了馬來西亞的飲食文化中。例如，在茶餐廳中常見的海南蒸麵包、海南咖啡、海南雞扒等，已經成為了跨越族裔界限的受歡迎美食。這些菜品不再僅僅代表海南族群，而是成為連結不同族群的紐帶。', 129, 'https://flavorinsight.com/wp-content/uploads/2024/10/7y1rubm2cxvian.mp3
3184800
audio/mpeg
');
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M59K5NA5PHCPA9ERZ0R9SN7D', 'malaysia-deep-travel-guide', 'published', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2024-10-28T11:02:55.000Z', '2026-10-19 22:59:59', '2024-10-28T11:02:55.000Z', NULL, NULL, 7, '01M5AYXR9BT6B8YW4CHT9QJ8MP', NULL, 'zh-TW', '01M59K5NA5PHCPA9ERZ0R9SN7D', '馬來筆記 Part5 未完待續', '{"id":"01M59MGY742NX3FD4E4P39VZAM","provider":"local","filename":"IMG_20240829_231927-1-scaled.jpg","mimeType":"image/jpeg","width":2560,"height":2142,"focalX":0.2584,"focalY":0.0874,"alt":"","meta":{"storageKey":"01M59MGY742NX3FD4E4P39VZAM.jpg","caption":null,"blurhash":null,"dominantColor":null}}', '[{"_type":"block","_key":"key-2-gaokt","style":"normal","children":[{"_type":"span","_key":"5o3khxy63","text":""}]},{"_type":"block","_key":"e0mc5z4yj","style":"normal","children":[{"_type":"span","_key":"key-1-ln575","text":"馬來西亞系列，寫到這裡已經遠超我最起初的預期，我算過大概三萬多字，起初只是隨口答應檳城的朋友們分享這趟旅行紀錄，他們希望我跟更多台灣人宣傳馬來西亞觀光，最後，內容也跳脫了當下的旅遊記錄，而是凝聚這些年我的所見所聞所思所想，希望8篇深度書寫的成果，能回報自 2020 年疫情開始到這趟旅行期間，大馬友人們對我的諸多照顧。"}]},{"_type":"block","_key":"key-5-gsn80","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-4-pl94f","text":"馬來筆記 Part.1 行路不難(上)","marks":["key-3-mhb00"]}],"markDefs":[{"_type":"link","_key":"key-3-mhb00","href":"/posts/smoothtripml1","blank":true}]},{"_type":"block","_key":"key-8-713pl","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-7-8tn2b","text":"馬來筆記 Part.1 行路不難(中)","marks":["key-6-rt9gb"]}],"markDefs":[{"_type":"link","_key":"key-6-rt9gb","href":"/posts/smoothtripml2","blank":true}]},{"_type":"block","_key":"key-11-0qzis","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-10-ebqte","text":"馬來筆記 Part.1 行路不難(下)","marks":["key-9-u056l"]}],"markDefs":[{"_type":"link","_key":"key-9-u056l","href":"/posts/smoothtripml3","blank":true}]},{"_type":"block","_key":"key-14-09pyz","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-13-6fjbb","text":"馬來筆記 Part.2 折衷的共存智慧","marks":["key-12-y0fqc"]}],"markDefs":[{"_type":"link","_key":"key-12-y0fqc","href":"/posts/livingwisdom","blank":true}]},{"_type":"block","_key":"key-17-u8dxa","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-16-rmg38","text":"馬來筆記 Part.3 從檳城看見台南的府城味","marks":["key-15-gmhgx"]}],"markDefs":[{"_type":"link","_key":"key-15-gmhgx","href":"/posts/penangtotainan","blank":true}]},{"_type":"block","_key":"key-20-2qh8u","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-19-kq569","text":"馬來筆記 Part4 再談馬來西亞飲食（上）","marks":["key-18-a52ih"]}],"markDefs":[{"_type":"link","_key":"key-18-a52ih","href":"/posts/malaysianfood1","blank":true}]},{"_type":"block","_key":"key-23-94xm6","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-22-w6d5j","text":"馬來筆記 Part4 再談馬來西亞飲食（中）","marks":["key-21-hxvta"]}],"markDefs":[{"_type":"link","_key":"key-21-hxvta","href":"/posts/malaysianfood2","blank":true}]},{"_type":"block","_key":"key-26-xvec5","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-25-4t5hx","text":"馬來筆記 Part4 再談馬來西亞飲食（下）","marks":["key-24-8k5sz"]}],"markDefs":[{"_type":"link","_key":"key-24-8k5sz","href":"/posts/malaysianfood3","blank":true}]},{"_type":"block","_key":"key-28-n406u","style":"normal","children":[{"_type":"span","_key":"key-27-q0tfq","text":"這系列文章不像遊記、食記，也不像分析報告，更多的是一個文化研究者&長期投資者，企圖在旅途中去更深度認知大馬社會的消費與文化脈絡，因為馬來西亞的飲食文化資本異常高，無論在文化研究或商業探查，都有很高的價值與潛力，不僅是為了旅遊，若你本身是想去創業或投資，這系列文應能給你些許文化 insights。當然，如果是想去旅遊，相信也能讓你對大馬社會有事前的深刻認識。"}]},{"_type":"block","_key":"key-30-eqjvp","style":"normal","children":[{"_type":"span","_key":"key-29-60gpo","text":"傳統商業分析習慣把人當消費者，忽視消費習慣背後的行程脈絡，下意識就以商業目標為導向，過於急切的定出結論，許多投資人在做股票研究時，也把商業分析的諸多壞毛病學起來，但在人類學或其他社會學科重視觀察，梳理社群發展脈絡、洞察社群關係與族群的行為價值觀，勝過於下結論。"}]},{"_type":"block","_key":"key-32-8v2uh","style":"normal","children":[{"_type":"span","_key":"key-31-m26x2","text":"想像一下，你要對一家遠在美國的陌生公司做投資決策，跟台灣企業想去開拓相對陌生的東南亞市場，又或是與 100 ~400 年前主動或被動去南洋找生計的明清先民相比，其實要面對的問題情境都是極為相似，想成功的關鍵點都在於讓自己能更精確的認知並洞察當地社群脈絡的真實模樣，才能找出最具潛力的機會，忽視脈絡思考的人，可能僥倖短暫成功，卻不可能長期獲勝。"}]},{"_type":"block","_key":"key-39-g3axk","style":"normal","children":[{"_type":"span","_key":"key-33-pj4ri","text":"想寫的還很多，甚至有些篇草稿尚待完成，例如"},{"_type":"span","_key":"key-34-4g5g9","text":"台灣餐飲在大馬的發展現況、馬來西亞的現代餐飲風貌、零售業特色、博物館","marks":["strong"]},{"_type":"span","_key":"key-35-fxryu","text":"之類，不過我本職還有許多投資課題要處理，暫時不再花時間接續書寫了，明年還會去大馬走走，屆時再考慮再提筆繼續寫，希望這系列對各位有幫助，也別忘了把馬來西亞列入你的旅遊清單。有興趣交流的朋友，也可"},{"_type":"span","_key":"key-37-vysvz","text":"連繫我","marks":["key-36-26pl6"]},{"_type":"span","_key":"key-38-fs45o","text":"。"}],"markDefs":[{"_type":"link","_key":"key-36-26pl6","href":"https://x.com/intent/follow?screen_name=austinsayhi","blank":true}]},{"_type":"block","_key":"key-41-d489s","style":"normal","children":[{"_type":"span","_key":"key-40-p31s0","text":"下面整理一些個人有在追蹤的馬來西亞資訊與過往相關的閱讀，供各位參考。"}]},{"_type":"block","_key":"key-43-ltd2d","style":"h3","children":[{"_type":"span","_key":"key-42-glqjs","text":"FB 粉專"}]},{"_type":"block","_key":"key-59-579va","style":"normal","children":[{"_type":"span","_key":"key-45-mh9z9","text":"日本人妻的無限創作\n","marks":["key-44-crgfk"]},{"_type":"span","_key":"key-46-7trj4","text":"很神奇的緣分，我疫情時偶然追蹤到小希的臉書，只是當成一個旅居馬來西亞的親子美食分享帳在看，直到她要在馬來西亞出書【貓咪帶我闖入迷霧森林-只為了和你們相遇】，才在相關介紹中發現原來她在台灣也出過一本書【日本人妻的無限料理】，正巧我當年就有買！沒想到過了六、七年，竟然追到同一個人，在這美食當道的年代，誇口自己愛美食的人居多，而無論什麼食物都能嚐出樂趣的人不多，大推她粉專。\n"},{"_type":"span","_key":"key-48-brf2t","text":"陳靜宜老師的臉書\n","marks":["key-47-7o5ao"]},{"_type":"span","_key":"key-49-2kjyu","text":"深耕大馬飲食文化的台灣第一人，在馬來媒體也有專欄，要怎麼提高飲食消費品味與文化涵養？跟懂吃的人學著吃出門道！\n"},{"_type":"span","_key":"key-51-nvi0h","text":"劲在槟城 / Exploring Penang\n","marks":["key-50-giltw"]},{"_type":"span","_key":"key-52-y2ki2","text":"非常在地的檳城美食分享\n"},{"_type":"span","_key":"key-54-gpilm","text":"Penang Foodie\n","marks":["key-53-r1scl"]},{"_type":"span","_key":"key-55-1pk9y","text":"巨量的檳城美食情報\n"},{"_type":"span","_key":"key-57-dfyyr","text":"馬拉妹出閘\n","marks":["key-56-rcv7j"]},{"_type":"span","_key":"key-58-7aylp","text":"馬來西亞的知名飲食文化工作者"}],"markDefs":[{"_type":"link","_key":"key-44-crgfk","href":"https://www.facebook.com/kaznozokazuki","blank":true},{"_type":"link","_key":"key-47-7o5ao","href":"https://www.facebook.com/profile.php?id=100070196771972&locale=zh_TW","blank":true},{"_type":"link","_key":"key-50-giltw","href":"https://www.facebook.com/Everything.About.Penang","blank":true},{"_type":"link","_key":"key-53-r1scl","href":"https://www.facebook.com/penangfoodie","blank":true},{"_type":"link","_key":"key-56-rcv7j","href":"https://www.facebook.com/malaimui1977/","blank":true}]},{"_type":"block","_key":"key-61-dqty4","style":"h3","children":[{"_type":"span","_key":"key-60-b8pai","text":"YT 頻道"}]},{"_type":"block","_key":"key-70-zxdxj","style":"normal","children":[{"_type":"span","_key":"key-63-u3s8x","text":"跟着阿宏找Lobang\n","marks":["key-62-bqbhf"]},{"_type":"span","_key":"key-64-28lbm","text":"宛如大馬版的搶救貧窮大作戰的《"},{"_type":"span","_key":"key-66-okyr4","text":"六叔來幫忙","marks":["key-65-o3b9a"]},{"_type":"span","_key":"key-67-lefet","text":"》系列，讓我第一次認識這位認真的大馬網紅。\n"},{"_type":"span","_key":"key-69-vx3g3","text":"迷鹿与高羊","marks":["key-68-6bx3p"]}],"markDefs":[{"_type":"link","_key":"key-62-bqbhf","href":"https://www.youtube.com/@lobang"},{"_type":"link","_key":"key-65-o3b9a","href":"https://youtube.com/playlist?list=PLKnLmlBXcOSSBYSwoaOH_lWcN2Zg3bTwX&si=ciB-NJ7irgoo0y_k"},{"_type":"link","_key":"key-68-6bx3p","href":"https://www.youtube.com/@higoatohdeer/playlists"}]},{"_type":"block","_key":"key-72-60ca1","style":"h3","children":[{"_type":"span","_key":"key-71-0zvs0","text":"媒體"}]},{"_type":"block","_key":"key-75-0eq7k","style":"normal","children":[{"_type":"span","_key":"key-74-s4y0e","text":"https://penangfoodie.com/","marks":["key-73-wfxu3"]}],"markDefs":[{"_type":"link","_key":"key-73-wfxu3","href":"https://penangfoodie.com/","blank":true}]},{"_type":"block","_key":"key-78-fortk","style":"normal","children":[{"_type":"span","_key":"key-77-avoyb","text":"星洲日報副刊","marks":["key-76-ibj7m"]}],"markDefs":[{"_type":"link","_key":"key-76-ibj7m","href":"https://www.sinchew.com.my/category/%E5%89%AF%E5%88%8A/%E4%B8%93%E6%A0%8F-%E5%89%AF%E5%88%8A/%E6%96%87%E5%8C%96%E7%A9%BA%E9%97%B4","blank":true}]},{"_type":"block","_key":"key-80-lkdsw","style":"h3","children":[{"_type":"span","_key":"key-79-f6xp3","text":"書籍太多了就不放"}]}]', '想像一下，你要對一家遠在美國的陌生公司做投資決策，跟台灣企業想去開拓相對陌生的東南亞市場，又或是與 100 ~400 年前主動或被動去南洋找生計的明清先民相比，其實要面對的問題情境都是極為相似', 116, NULL);
INSERT OR REPLACE INTO "ec_posts" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "featured_image", "content", "excerpt", "views", "enclosure") VALUES ('01M5AYTE2N6S11EZAQEQ3NPGS3', 'test', 'draft', '01M59HRWZE00Q2KMA31TJWZ6HQ', '01M59K4HEF76NEMFZDYDMYYA0K', '2026-10-19T20:49:32.245Z', '2026-10-19T20:49:32.245Z', NULL, NULL, NULL, 3, NULL, NULL, 'zh-TW', '01M5AYTE2N6S11EZAQEQ3NPGS3', 'test', NULL, '[{"_type":"block","_key":"0t19bci1o","style":"blockquote","children":[{"_type":"span","_key":"fiuoz1tv4","text":"isiisoiosss"}]},{"_type":"htmlBlock","_key":"card-cultural-lore-block-0","html":"<div class=\"fi-card fi-card-lore my-8\">\n  <div class=\"fi-card-header\">\n    <span class=\"fi-card-badge fi-badge-gold\"><i class=\"fas fa-landmark\"></i> CULTURAL LORE 文史典故</span>\n  </div>\n  <div class=\"fi-card-body\">\n    <h3 class=\"fi-card-title fi-title-gold\">十九世紀海港宗族與街頭小吃起源</h3>\n    <p class=\"fi-card-text\">十九世紀中葉華人移民大舉遷徙至檳城與台南兩地海港，碼頭苦力在繁重勞動之餘，以最平價的豬油、豆芽與麵條大火翻炒，演變成今日生猛鑊氣的街頭代表小吃。</p>\n  </div>\n</div>"},{"_type":"htmlBlock","_key":"faq-block-0","html":"<div class=\"faq-container my-10\" id=\"faq\">\n<h2 class=\"hub-section-title\"><i class=\"fas fa-circle-question\"></i> 本篇重點導覽問答（FAQ）</h2>\n<div class=\"faq-accordion\">\n<details class=\"faq-item\" open=\"\">\n<summary class=\"faq-summary\"><span class=\"faq-summary-q\"><span class=\"faq-q-badge\">Q1</span>為什麼說馬來西亞檳城與台灣台南的城市肌理與常民文化高度相似？</span><i class=\"fas fa-chevron-down faq-summary-icon\"></i></summary>\n<div class=\"faq-content\">\n<p>檳城喬治市與台南府城同為海港移民重要起點，皆保留了極為完整的閩南宗族廟宇、傳統街屋空間、以福建話（台語）為主的語言環境，以及將吃當作生命核心哲學的慢活步調。</p>\n</div>\n</details>\n<details class=\"faq-item\">\n<summary class=\"faq-summary\"><span class=\"faq-summary-q\"><span class=\"faq-q-badge\">Q2</span>檳城炒粿條與台南炒鱔魚意麵在烹調哲學上有何共同靈魂？</span><i class=\"fas fa-chevron-down faq-summary-icon\"></i></summary>\n<div class=\"faq-content\">\n<p>兩者皆極致講求「生猛鑊氣」與豬油／豬油渣的巧妙運用。沒了大火快炒逼出的高溫鑊氣，炒粿條與鱔魚意麵就失去了靈魂；這種對火候極致的堅持正是兩地小吃職人共通的美學標準。</p>\n</div>\n</details>\n<details class=\"faq-item\">\n<summary class=\"faq-summary\"><span class=\"faq-summary-q\"><span class=\"faq-q-badge\">Q3</span>為什麼研究台灣常民飲食與文化歷史，非常推薦走一趟檳城？</span><i class=\"fas fa-chevron-down faq-summary-icon\"></i></summary>\n<div class=\"faq-content\">\n<p>檳城保留了許多在現代台灣都市化過程中逐漸式微的古早味技法與宗族文化地景，走訪檳城就像走進一座活態常民生活博物館，能為台灣研究者提供珍貴的歷史對照坐標。</p>\n</div>\n</details>\n</div>\n</div>"},{"_type":"htmlBlock","_key":"card-venue-guide-block-0","html":"<div class=\"fi-card fi-card-venue my-8\">\n  <div class=\"fi-card-header\">\n    <div class=\"fi-card-badge fi-badge-accent\"><i class=\"fas fa-star\"></i> 老饕嚴選推薦</div>\n    <span class=\"fi-card-meta\"><i class=\"fas fa-location-dot\"></i> 喬治市古蹟核心區</span>\n  </div>\n  <div class=\"fi-card-body\">\n    <h3 class=\"fi-card-title\">暹羅路炭火炒粿條（Siam Road Char Koay Teow）</h3>\n    <div class=\"fi-card-tags\">\n      <span class=\"fi-tag\">招牌必點：鴨蛋加辣炒粿條</span>\n      <span class=\"fi-tag\">推薦時段：平日下午 2:00</span>\n      <span class=\"fi-tag\">推薦度：★★★★★</span>\n    </div>\n    <p class=\"fi-card-text\">高齡七十多歲的謝師傅以古法木炭爐快炒，每鍋僅炒一至兩盤。炭火高溫逼出濃烈鑊氣，鴨蛋香與自製豬油渣交織，是檳城街頭極致工藝的代表作。</p>\n  </div>\n</div>"},{"_type":"htmlBlock","_key":"card-artisan-quote-block-0","html":"<div class=\"fi-card fi-card-quote my-8\">\n  <div class=\"fi-quote-mark\">“</div>\n  <blockquote class=\"fi-quote-content\">\n    「火候不能急，鐵鍋夠熱、油爆要脆，鑊氣是一口氣逼出來的，多一秒就焦，少一秒就死。」\n  </blockquote>\n  <div class=\"fi-quote-author\">\n    <span class=\"fi-author-name\">謝國樑</span>\n    <span class=\"fi-author-title\">—— 檳城七十年炭火炒粿條 掌杓職人</span>\n  </div>\n</div>"},{"_type":"htmlBlock","_key":"card-pro-tip-block-0","html":"<div class=\"fi-card fi-card-tip my-8\">\n  <div class=\"fi-card-header\">\n    <span class=\"fi-card-badge fi-badge-amber\"><i class=\"fas fa-fire-flame-curved\"></i> PRO TIP 賞味秘訣</span>\n  </div>\n  <div class=\"fi-card-body\">\n    <h3 class=\"fi-card-title\">黃金賞味三分鐘與點餐暗語</h3>\n    <ul class=\"fi-card-list\">\n      <li><strong>趁熱即食：</strong>出鍋後三分鐘內豬油渣仍保脆度，若外帶悶在盒子裡，鑊氣與脆度將大打折扣。</li>\n      <li><strong>在地點餐術語：</strong>請指定「加鴨蛋」（Duck Egg），鴨蛋脂香與黏稠度遠勝雞蛋，裹附粿條的口感截然不同。</li>\n      <li><strong>排隊時間預估：</strong>建議避開週末中午尖峰，平日下午兩點前至現場通常等候時間少於 20 分鐘。</li>\n    </ul>\n  </div>\n</div>"},{"_type":"htmlBlock","_key":"card-tasting-note-block-0","html":"<div class=\"fi-card fi-card-tasting my-8\">\n  <div class=\"fi-card-header\">\n    <span class=\"fi-card-badge\"><i class=\"fas fa-feather-pointed\"></i> TASTING NOTE 風味筆記</span>\n  </div>\n  <div class=\"fi-card-body\">\n    <h3 class=\"fi-card-title\">蝦醬與羅望子的酸甘平衡</h3>\n    <p class=\"fi-card-text\">正宗檳城亞參叻沙的靈魂在於去骨鯖魚熬製的濃濁魚湯，伴隨新鮮薄荷葉、薑花碎與切絲黃瓜。入口初覺酸嗆開胃，尾韻則是濃郁蝦膏引出的深沉甘醇，是極致的南洋對比美學。</p>\n  </div>\n</div>"}]', NULL, NULL, NULL);
