INSERT OR REPLACE INTO "options" ("name", "value", "revision") VALUES ('plugin:seo:settings:defaultDescription', '"風味洞察 From Flavor to Insight — 由 Austin 撰寫，以個人深度視角探索各國與台灣的飲食文化、歷史脈絡與在地滋味。"', '4a997f47-275d-4ddf-957a-61b7654a0628');
